99	/****************************************************************************
100	 * Cached GPIO pin state for fast bit-bang
101	 *
102	 * Instead of read-modify-write on every gpio_write() call, we cache the
103	 * CFG base value (with OUTPUT=0) and register address at setup time.
104	 * Setting a pin HIGH is then a single putreg32(base | OUTPUT_BIT).
105	 ****************************************************************************/
106	
107	typedef struct
108	{
109	  uintptr_t addr;   /* BK7258_GPIO_CFG(pin) address */
110	  uint32_t base_lo; /* CFG with OUTPUT bit cleared */
111	  uint32_t base_hi; /* CFG with OUTPUT bit set */
112	} gpio_cache_t;
113	
114	static gpio_cache_t g_cache_sclk;
115	static gpio_cache_t g_cache_mosi;
116	static gpio_cache_t g_cache_cs;
117	static gpio_cache_t g_cache_dc;
118	
119	/* Display geometry */
120	
121	#define LCD_WIDTH      160
122	#define LCD_HEIGHT     160
123	#define LCD_BPP        16  /* RGB565 */
124	
125	/* Test square size (Stage C) */
126	
127	#define SQ_SIZE        40
128	
129	/* SPI bit-bang delay: a few NOPs for timing margin. */
130	
131	#define spi_delay() \
132	  do { \
133	    __asm__ volatile("nop; nop; nop; nop;"); \
134	  } while (0)
