136	/****************************************************************************
137	 * Private Functions
138	 ****************************************************************************/
139	
140	/****************************************************************************
141	 * Name: gpio_set_output
142	 ****************************************************************************/
143	
144	static void gpio_set_output(int pin)
145	{
146	  uint32_t cfg = getreg32(BK7258_GPIO_CFG(pin));
147	
148	  cfg &= ~GPIO_CFG_SECOND_FUNC;  /* GPIO mode (bit6 = 0) */
149	  cfg &= ~GPIO_CFG_OUTPUT_EN;    /* output enable (bit3 active-low: 0 = on) */
150	  cfg &= ~GPIO_CFG_INPUT_EN;     /* input off (bit2: 0=off) */
151	  putreg32(cfg, BK7258_GPIO_CFG(pin));
152	}
153	
154	/****************************************************************************
155	 * Name: gpio_write
156	 ****************************************************************************/
157	
158	static void gpio_write(int pin, int val)
159	{
160	  uint32_t cfg = getreg32(BK7258_GPIO_CFG(pin));
161	
162	  if (val)
163	    {
164	      cfg |= GPIO_CFG_OUTPUT;
165	    }
166	  else
167	    {
168	      cfg &= ~GPIO_CFG_OUTPUT;
169	    }
170	
171	  putreg32(cfg, BK7258_GPIO_CFG(pin));
172	}
173	
174	/****************************************************************************
175	 * Name: gpio_set_output_cached
176	 *
177	 * Description:
178	 *   Configure pin as GPIO output and cache the CFG register values
179	 *   for fast putreg32-only writes (no getreg32 read needed later).
180	 *
181	 ****************************************************************************/
182	
183	static void gpio_set_output_cached(int pin, gpio_cache_t *c)
184	{
185	  uint32_t cfg;
186	
187	  c->addr = BK7258_GPIO_CFG(pin);
188	  cfg = getreg32(c->addr);
189	  cfg &= ~GPIO_CFG_SECOND_FUNC;
190	  cfg &= ~GPIO_CFG_OUTPUT_EN;
191	  cfg &= ~GPIO_CFG_INPUT_EN;
192	  cfg &= ~GPIO_CFG_OUTPUT;   /* output = 0 */
193	  putreg32(cfg, c->addr);
194	  c->base_lo = cfg;            /* OUTPUT=0 */
195	  c->base_hi = cfg | GPIO_CFG_OUTPUT; /* OUTPUT=1 */
196	}
