198	/****************************************************************************
199	 * Name: gpio_write_fast
200	 *
201	 * Description:
202	 *   Set pin via cached values — no read-modify-write, just a single
203	 *   putreg32.  ~2x faster than gpio_write().
204	 *
205	 ****************************************************************************/
206	
207	static inline void gpio_write_fast(const gpio_cache_t *c, int val)
208	{
209	  putreg32(val ? c->base_hi : c->base_lo, c->addr);
210	}
