212	/****************************************************************************
213	 * Name: lcd_set_pins / lcd_setup_pins
214	 ****************************************************************************/
215	
216	static void lcd_set_pins(const lcd_pins_t *pins)
217	{
218	  g_active_pins = pins;
219	}
220	
221	static void lcd_setup_pins(const lcd_pins_t *pins)
222	{
223	  lcd_set_pins(pins);
224	  gpio_set_output(pins->rst);
225	
226	  /* Cache SCLK/MOSI/CS/DC for fast bit-bang */
227	
228	  gpio_set_output_cached(pins->sclk, &g_cache_sclk);
229	  gpio_set_output_cached(pins->mosi, &g_cache_mosi);
230	  gpio_set_output_cached(pins->cs,   &g_cache_cs);
231	  gpio_set_output_cached(pins->dc,   &g_cache_dc);
232	
233	  /* Initial idle state: CS=HIGH, DC=HIGH, SCLK=LOW, MOSI=LOW */
234	
235	  gpio_write_fast(&g_cache_cs,   1);
236	  gpio_write_fast(&g_cache_dc,   1);
237	  gpio_write_fast(&g_cache_sclk, 0);
238	  gpio_write_fast(&g_cache_mosi, 0);
239	}
240	
241	/****************************************************************************
242	 * Name: spi_write_byte
243	 *
244	 * Description:
245	 *   Bit-bang one byte, MSB-first, SPI mode 0.
246	 *   Uses cached GPIO values (no getreg32 read) and no NOP delay.
247	 *   GC9D01 can handle fast SPI clock; add back one spi_delay() if
248	 *   display shows corruption.
249	 *
250	 ****************************************************************************/
251	
252	static void spi_write_byte(uint8_t byte)
253	{
254	  int bit;
255	
256	  for (bit = 7; bit >= 0; bit--)
257	    {
258	      gpio_write_fast(&g_cache_mosi, (byte >> bit) & 1);
259	      gpio_write_fast(&g_cache_sclk, 1);
260	      gpio_write_fast(&g_cache_sclk, 0);
261	    }
262	}
263	
264	/****************************************************************************
265	 * Name: lcd_send_cmd / lcd_send_data / lcd_send_cmd_data
266	 ****************************************************************************/
267	
268	static void lcd_send_cmd(uint8_t cmd)
269	{
270	  gpio_write_fast(&g_cache_dc, 0);
271	  gpio_write_fast(&g_cache_cs, 0);
272	  spi_write_byte(cmd);
273	  gpio_write_fast(&g_cache_cs, 1);
274	}
275	
276	static void lcd_send_data(const uint8_t *data, int len)
277	{
278	  int i;
279	
280	  gpio_write_fast(&g_cache_dc, 1);
281	  gpio_write_fast(&g_cache_cs, 0);
282	  for (i = 0; i < len; i++)
283	    {
284	      spi_write_byte(data[i]);
285	    }
286	
287	  gpio_write_fast(&g_cache_cs, 1);
288	}
289	
290	static void lcd_send_cmd_data(uint8_t cmd, const uint8_t *data, int len)
291	{
292	  lcd_send_cmd(cmd);
293	  if (len > 0)
294	    {
295	      lcd_send_data(data, len);
296	    }
297	}
