299	/****************************************************************************
300	 * Name: lcd_init_sequence
301	 *
302	 * Description:
303	 *   Full GC9D01 init sequence from ARMINO lcd_spi_gc9d01.c.
304	 *   If display_on is true, sends 0x29 (display on) at the end;
305	 *   otherwise leaves the display off so the caller can fill the
306	 *   framebuffer first (avoids flash of uninitialised GRAM).
307	 *
308	 ****************************************************************************/
309	
310	static void lcd_init_sequence(bool display_on)
311	{
312	  lcd_send_cmd(0xfe);
313	  lcd_send_cmd(0xef);
314	
315	  lcd_send_cmd_data(0x80, (const uint8_t *)"\xff", 1);
316	  lcd_send_cmd_data(0x81, (const uint8_t *)"\xff", 1);
317	  lcd_send_cmd_data(0x82, (const uint8_t *)"\xff", 1);
318	  lcd_send_cmd_data(0x83, (const uint8_t *)"\xff", 1);
319	  lcd_send_cmd_data(0x84, (const uint8_t *)"\xff", 1);
320	  lcd_send_cmd_data(0x85, (const uint8_t *)"\xff", 1);
321	  lcd_send_cmd_data(0x86, (const uint8_t *)"\xff", 1);
322	  lcd_send_cmd_data(0x87, (const uint8_t *)"\xff", 1);
323	  lcd_send_cmd_data(0x88, (const uint8_t *)"\xff", 1);
324	  lcd_send_cmd_data(0x89, (const uint8_t *)"\xff", 1);
325	  lcd_send_cmd_data(0x8a, (const uint8_t *)"\xff", 1);
326	  lcd_send_cmd_data(0x8b, (const uint8_t *)"\xff", 1);
327	  lcd_send_cmd_data(0x8c, (const uint8_t *)"\xff", 1);
328	  lcd_send_cmd_data(0x8d, (const uint8_t *)"\xff", 1);
329	  lcd_send_cmd_data(0x8e, (const uint8_t *)"\xff", 1);
330	  lcd_send_cmd_data(0x8f, (const uint8_t *)"\xff", 1);
331	
332	  lcd_send_cmd_data(0x3a, (const uint8_t *)"\x05", 1);
333	  lcd_send_cmd_data(0xec, (const uint8_t *)"\x01", 1);
334	  lcd_send_cmd_data(0x74,
335	    (const uint8_t *)"\x02\x0e\x00\x00\x00\x00\x00", 7);
336	  lcd_send_cmd_data(0x98, (const uint8_t *)"\x3e\x99\x3e", 3);
337	  lcd_send_cmd_data(0xb5, (const uint8_t *)"\x0d\x0d", 2);
338	  lcd_send_cmd_data(0x60,
339	    (const uint8_t *)"\x38\x0f\x79\x67", 4);
340	  lcd_send_cmd_data(0x61,
341	    (const uint8_t *)"\x38\x11\x79\x67", 4);
342	  lcd_send_cmd_data(0x64,
343	    (const uint8_t *)"\x38\x17\x71\x5f\x79\x67", 6);
344	  lcd_send_cmd_data(0x65,
345	    (const uint8_t *)"\x38\x13\x71\x5b\x79\x67", 6);
346	  lcd_send_cmd_data(0x6a, (const uint8_t *)"\x00\x00", 2);
347	  lcd_send_cmd_data(0x6c,
348	    (const uint8_t *)"\x22\x02\x22\x02\x22\x22\x50", 7);
349	  lcd_send_cmd_data(0x6e,
350	    (const uint8_t *)"\x03\x03\x01\x01\x00\x00"
351	                     "\x0f\x0f\x0d\x0d\x0b\x0b"
352	                     "\x09\x09\x00\x00\x00\x00"
353	                     "\x0a\x0a\x0c\x0c\x0e\x0e"
354	                     "\x10\x10\x00\x00\x02\x02"
355	                     "\x04\x04", 32);
356	  lcd_send_cmd_data(0xbf, (const uint8_t *)"\x01", 1);
357	  lcd_send_cmd_data(0xf9, (const uint8_t *)"\x40", 1);
358	  lcd_send_cmd_data(0x9b, (const uint8_t *)"\x3b", 1);
359	  lcd_send_cmd_data(0x93, (const uint8_t *)"\x33\x7f\x00", 3);
360	  lcd_send_cmd_data(0x7e, (const uint8_t *)"\x30", 1);
361	  lcd_send_cmd_data(0x70,
362	    (const uint8_t *)"\x0d\x02\x08\x0d\x02\x08", 6);
363	  lcd_send_cmd_data(0x71,
364	    (const uint8_t *)"\x0d\x02\x08", 3);
365	  lcd_send_cmd_data(0x91, (const uint8_t *)"\x0e\x09", 2);
366	  lcd_send_cmd_data(0xc3, (const uint8_t *)"\x18", 1);
367	  lcd_send_cmd_data(0xc4, (const uint8_t *)"\x18", 1);
368	  lcd_send_cmd_data(0xc9, (const uint8_t *)"\x3c", 1);
369	  lcd_send_cmd_data(0xf0,
370	    (const uint8_t *)"\x13\x15\x04\x05\x01\x38", 6);
371	  lcd_send_cmd_data(0xf2,
372	    (const uint8_t *)"\x13\x15\x04\x05\x01\x34", 6);
373	  lcd_send_cmd_data(0xf1,
374	    (const uint8_t *)"\x4b\xb8\x7b\x34\x35\xef", 6);
375	  lcd_send_cmd_data(0xf3,
376	    (const uint8_t *)"\x47\xb4\x72\x34\x35\xda", 6);
377	  lcd_send_cmd_data(0x36, (const uint8_t *)"\x00", 1);
378	
379	  lcd_send_cmd(0x34);  /* tearing effect off */
380	  lcd_send_cmd(0x11);  /* sleep out */
381	  up_mdelay(120);
382	
383	  if (display_on)
384	    {
385	      lcd_send_cmd(0x29);  /* display on */
386	    }
387	}
