402	/****************************************************************************
403	 * Name: lcd_fill_rect
404	 *
405	 * Description:
406	 *   Fill a rectangle (x0,y0)-(x1,y1) with a single RGB565 color.
407	 *   Much smaller than full-screen fill — avoids millions of bit-bangs.
408	 *
409	 ****************************************************************************/
410	
411	static void lcd_fill_rect(uint16_t x0, uint16_t y0,
412	                          uint16_t x1, uint16_t y1,
413	                          uint16_t color)
414	{
415	  uint8_t ca[4];
416	  uint8_t ra[4];
417	  uint8_t hi = (color >> 8) & 0xff;
418	  uint8_t lo = color & 0xff;
419	  int npix = (int)(x1 - x0 + 1) * (int)(y1 - y0 + 1);
420	  int i;
421	
422	  /* CASET */
423	
424	  ca[0] = (x0 >> 8) & 0xff;
425	  ca[1] = x0 & 0xff;
426	  ca[2] = (x1 >> 8) & 0xff;
427	  ca[3] = x1 & 0xff;
428	  lcd_send_cmd_data(0x2a, ca, 4);
429	
430	  /* RASET */
431	
432	  ra[0] = (y0 >> 8) & 0xff;
433	  ra[1] = y0 & 0xff;
434	  ra[2] = (y1 >> 8) & 0xff;
435	  ra[3] = y1 & 0xff;
436	  lcd_send_cmd_data(0x2b, ra, 4);
437	
438	  /* RAMWR + pixel data */
439	
440	  lcd_send_cmd(0x2c);
441	  gpio_write_fast(&g_cache_dc, 1);
442	  gpio_write_fast(&g_cache_cs, 0);
443	  for (i = 0; i < npix; i++)
444	    {
445	      spi_write_byte(hi);
446	      spi_write_byte(lo);
447	    }
448	
449	  gpio_write_fast(&g_cache_cs, 1);
450	}
451	
452	/****************************************************************************
453	 * Name: bk7258_lcd_blit_rgb565
454	 *
455	 * Description:
456	 *   Blit a full RGB565 framebuffer to the LCD.
457	 *   Sends CASET/RASET/RAMWR then streams pixel data in rows.
458	 *
459	 *   No scaling — the buffer must match w×h exactly.
460	 *   Buffer layout: big-endian RGB565 (high byte first), row-major.
461	 *
462	 *   Public so camera preview can call it.
463	 *
464	 ****************************************************************************/
465	
466	void bk7258_lcd_blit_rgb565(uint16_t x0, uint16_t y0,
467	                             uint16_t w, uint16_t h,
468	                             const uint8_t *rgb565)
469	{
470	  uint8_t ca[4];
471	  uint8_t ra[4];
472	  uint16_t x1 = x0 + w - 1;
473	  uint16_t y1 = y0 + h - 1;
474	  int row;
475	  int row_bytes = (int)w * 2;
476	
477	  /* CASET */
478	
479	  ca[0] = (x0 >> 8) & 0xff;
480	  ca[1] = x0 & 0xff;
481	  ca[2] = (x1 >> 8) & 0xff;
482	  ca[3] = x1 & 0xff;
483	  lcd_send_cmd_data(0x2a, ca, 4);
484	
485	  /* RASET */
486	
487	  ra[0] = (y0 >> 8) & 0xff;
488	  ra[1] = y0 & 0xff;
489	  ra[2] = (y1 >> 8) & 0xff;
490	  ra[3] = y1 & 0xff;
491	  lcd_send_cmd_data(0x2b, ra, 4);
492	
493	  /* RAMWR + pixel data, one row at a time */
494	
495	  lcd_send_cmd(0x2c);
496	
497	  for (row = 0; row < (int)h; row++)
498	    {
499	      gpio_write_fast(&g_cache_dc, 1);
500	      gpio_write_fast(&g_cache_cs, 0);
501	
502	      const uint8_t *rowp = rgb565 + row * row_bytes;
503	      int i;
504	      for (i = 0; i < row_bytes; i++)
505	        {
506	          spi_write_byte(rowp[i]);
507	        }
508	
509	      gpio_write_fast(&g_cache_cs, 1);
510	    }
511	}
