513	/****************************************************************************
514	 * Name: bk7258_lcd_preview_init
515	 *
516	 * Description:
517	 *   Initialize the left-screen LCD for camera preview use.
518	 *   Enables LDO_3V3 (P52), backlight (P25), configures SPI pins,
519	 *   resets GC9D01, runs init sequence, turns display on, fills
520	 *   with black to confirm screen is alive.
521	 *
522	 *   Reuses the same static functions that lcdtest uses — no
523	 *   duplicated init sequence.
524	 *
525	 *   Safe to call even if lcdtest has previously run — pin setup
526	 *   is idempotent (gpio_set_output + cached values).
527	 *
528	 * Returns:
529	 *   0 on success.
530	 *
531	 ****************************************************************************/
532	
533	int bk7258_lcd_preview_init(void)
534	{
535	  /* LCD 3.3V power supply — P52 enables U3 (ME6211C33 LDO) */
536	
537	  gpio_set_output(LCD_PIN_LDO33_EN);
538	  gpio_write(LCD_PIN_LDO33_EN, 1);
539	  up_mdelay(50);   /* wait for LDO output to stabilize */
540	
541	  /* Backlight on */
542	
543	  gpio_set_output(LCD_PIN_BL);
544	  gpio_write(LCD_PIN_BL, 1);
545	
546	  /* Configure left-screen SPI pins (P2/P3/P4/P5/P45) */
547	
548	  lcd_setup_pins(&g_lcd_left);
549	
550	  /* Hardware reset: RST low → 15ms → RST high → 120ms */
551	
552	  gpio_write(g_active_pins->rst, 0);
553	  up_mdelay(15);
554	  gpio_write(g_active_pins->rst, 1);
555	  up_mdelay(120);
556	
557	  /* GC9D01 init sequence with display_on */
558	
559	  lcd_init_sequence(true);
560	
561	  /* Fill black to confirm screen is alive */
562	
563	  lcd_fill_rect(0, 0, LCD_WIDTH - 1, LCD_HEIGHT - 1, 0x0000);
564	
565	  syslog(LOG_INFO,
566	         "[lcd] preview init done — screen should show black\n");
567	
568	  return 0;
569	}
