571	/****************************************************************************
572	 * Name: bk7258_lcd_preview_deinit
573	 *
574	 * Description:
575	 *   Release LCD resources after camera preview.
576	 *   Turns off backlight only.  P52 (LDO_3V3) stays on because
577	 *   other peripherals may depend on the 3.3V rail.
578	 *
579	 ****************************************************************************/
580	
581	void bk7258_lcd_preview_deinit(void)
582	{
583	  /* Backlight off — leave LDO_3V3 enabled */
584	
585	  gpio_write(LCD_PIN_BL, 0);
586	
587	  syslog(LOG_INFO, "[lcd] preview deinit — backlight off\n");
588	}
