590	/****************************************************************************
591	 * Name: sqrt_int — integer square root (Newton's method)
592	 ****************************************************************************/
593	
594	static int16_t sqrt_int(int32_t val)
595	{
596	  int32_t guess;
597	  int32_t next;
598	  int i;
599	
600	  if (val <= 0)
601	    {
602	      return 0;
603	    }
604	
605	  guess = val;
606	
607	  for (i = 0; i < 10; i++)
608	    {
609	      next = (guess + val / guess) / 2;
610	
611	      if (next >= guess)
612	        {
613	          break;
614	        }
615	
616	      guess = next;
617	    }
618	
619	  return (int16_t)guess;
620	}
