622	/****************************************************************************
623	 * Name: lcd_fill_circle
624	 *
625	 * Description:
626	 *   Fill a circle centred at (cx,cy) with radius r using scanline
627	 *   rendering.  Each scanline is a 1px-high lcd_fill_rect call.
628	 *
629	 ****************************************************************************/
630	
631	static void lcd_fill_circle(int16_t cx, int16_t cy, int16_t r,
632	                            uint16_t color)
633	{
634	  int16_t y;
635	  int16_t dx;
636	  int16_t x0;
637	  int16_t x1;
638	  int32_t r2 = (int32_t)r * r;
639	
640	  for (y = cy - r; y <= cy + r; y++)
641	    {
642	      int32_t dy  = (int32_t)(y - cy);
643	      int32_t rem = r2 - dy * dy;
644	
645	      if (rem < 0)
646	        {
647	          continue;
648	        }
649	
650	      dx = sqrt_int(rem);
651	      x0 = cx - dx;
652	      x1 = cx + dx;
653	
654	      if (x0 < 0)
655	        {
656	          x0 = 0;
657	        }
658	
659	      if (x1 >= LCD_WIDTH)
660	        {
661	          x1 = LCD_WIDTH - 1;
662	        }
663	
664	      if (y < 0 || y >= LCD_HEIGHT)
665	        {
666	          continue;
667	        }
668	
669	      lcd_fill_rect(x0, y, x1, y, color);
670	    }
671	}
672	
673	/****************************************************************************
674	 * Name: lcd_fill_round_rect
675	 *
676	 * Description:
677	 *   Fill a rounded rectangle centred at (cx,cy), width w, height h,
678	 *   corner radius r.  Built from one inner rect + four corner circles.
679	 *
680	 ****************************************************************************/
681	
682	static void lcd_fill_round_rect(int16_t cx, int16_t cy,
683	                                int16_t w, int16_t h,
684	                                int16_t r, uint16_t color)
685	{
686	  int16_t x0 = cx - w / 2;
687	  int16_t y0 = cy - h / 2;
688	  int16_t x1 = cx + w / 2;
689	  int16_t y1 = cy + h / 2;
690	
691	  /* Horizontal centre strip (full width, reduced height) */
692	
693	  lcd_fill_rect(x0, y0 + r, x1, y1 - r, color);
694	
695	  /* Vertical centre strip (reduced width, full height) */
696	
697	  lcd_fill_rect(x0 + r, y0, x1 - r, y1, color);
698	
699	  /* Four corner circles */
700	
701	  lcd_fill_circle(x0 + r, y0 + r, r, color);
702	  lcd_fill_circle(x1 - r, y0 + r, r, color);
703	  lcd_fill_circle(x0 + r, y1 - r, r, color);
704	  lcd_fill_circle(x1 - r, y1 - r, r, color);
705	}
