728	/****************************************************************************
729	 * Name: eye_draw_full
730	 *
731	 * Description:
732	 *   Full draw of the animated eye model on the current panel.
733	 *   Call once per eye before starting animation.
734	 *
735	 *   Background: black
736	 *   Iris:       cyan 0x07FF, centre (80,80), r=58
737	 *   Pupil:      black 0x0000, r=22, centre (80+gaze_dx, 80)
738	 *   Highlight:  white 0xFFFF, r=8, centre (80+gaze_dx-8, 80-10)
739	 *
740	 ****************************************************************************/
741	
742	#define EYE_CX        80
743	#define EYE_CY        80
744	#define EYE_IRIS_R    58
745	#define EYE_PUPIL_R   22
746	#define EYE_HIGHLIGHT_R 8
747	
748	static void eye_draw_full(int gaze_dx)
749	{
750	  int pcx = EYE_CX + gaze_dx;
751	
752	  syslog(LOG_INFO,
753	         "[eye] full draw gaze_dx=%d\n", gaze_dx);
754	
755	  /* Black background */
756	
757	  lcd_fill_rect(0, 0, LCD_WIDTH - 1, LCD_HEIGHT - 1, 0x0000);
758	
759	  /* Cyan iris */
760	
761	  lcd_fill_circle(EYE_CX, EYE_CY, EYE_IRIS_R, 0x07ff);
762	
763	  /* Black pupil */
764	
765	  lcd_fill_circle(pcx, EYE_CY, EYE_PUPIL_R, 0x0000);
766	
767	  /* White highlight (upper-left of pupil) */
768	
769	  lcd_fill_circle(pcx - 8, EYE_CY - 10,
770	                  EYE_HIGHLIGHT_R, 0xffff);
771	}
