773	/****************************************************************************
774	 * Name: eye_move_pupil
775	 *
776	 * Description:
777	 *   Local update: repaint old pupil position with iris colour, then
778	 *   draw pupil + highlight at the new position.  No full-screen fill.
779	 *
780	 ****************************************************************************/
781	
782	static void eye_move_pupil(int old_dx, int new_dx)
783	{
784	  int old_cx = EYE_CX + old_dx;
785	  int new_cx = EYE_CX + new_dx;
786	
787	  syslog(LOG_INFO,
788	         "[eye] move pupil %d -> %d\n", old_dx, new_dx);
789	
790	  /* Erase old pupil (r23 to catch anti-aliased edge) */
791	
792	  lcd_fill_circle(old_cx, EYE_CY, 23, 0x07ff);
793	
794	  /* Erase old highlight (extends beyond pupil r22) */
795	
796	  lcd_fill_circle(old_cx - 8, EYE_CY - 10, 10, 0x07ff);
797	
798	  /* Black pupil at new position */
799	
800	  lcd_fill_circle(new_cx, EYE_CY, EYE_PUPIL_R, 0x0000);
801	
802	  /* White highlight */
803	
804	  lcd_fill_circle(new_cx - 8, EYE_CY - 10,
805	                  EYE_HIGHLIGHT_R, 0xffff);
806	}
