914	/****************************************************************************
915	 * Official-website-style eye: white bg + blue iris + black eyelids
916	 *
917	 * Color palette (RGB565):
918	 *   0xFFFF  white  (background)
919	 *   0x02DF  sky-blue (iris) — try 0x001F for deeper blue
920	 *   0x0000  black  (pupil, eyelids)
921	 *   0xFFFF  white  (highlight)
922	 ****************************************************************************/
923	
924	#define OEYE_BG        0xFFFF  /* white */
925	#define OEYE_IRIS      0x02DF  /* sky-blue */
926	#define OEYE_PUPIL     0x0000  /* black */
927	#define OEYE_HL        0xFFFF  /* white highlight */
928	#define OEYE_LID       0x0000  /* black eyelid */
929	
930	#define OEYE_IRIS_R    56     /* blue iris with visible white border */
931	#define OEYE_PUPIL_R   28     /* black pupil */
932	#define OEYE_HL1_R     10     /* primary highlight upper-left */
933	#define OEYE_HL1_X     68     /* primary highlight centre */
934	#define OEYE_HL1_Y     68
935	#define OEYE_HL2_R     4      /* secondary highlight lower-right */
936	#define OEYE_HL2_X     92     /* secondary highlight centre */
937	#define OEYE_HL2_Y     92
938	
939	/* Iris bounding box — the only region we redraw per frame.
940	 * iris at (80,80) r56 → x,y ∈ [24,136].
941	 */
942	
943	#define OEYE_BOX_L     24
944	#define OEYE_BOX_R     136
945	#define OEYE_BOX_T     24
946	#define OEYE_BOX_B     136
947	
948	/* Eyelid Y boundaries for each expression */
949	
950	#define OEYE_NEUTRAL_TOP  16   /* neutral: upper lid covers y 0..16 */
951	#define OEYE_NEUTRAL_BOT  143  /* neutral: lower lid covers y 143..159 */
952	#define OEYE_HALF_TOP     50   /* half: upper lid covers y 0..50 */
953	#define OEYE_HALF_BOT     110  /* half: lower lid covers y 110..159 */
954	#define OEYE_BLINK_TOP    70   /* blink: black arc top edge */
955	#define OEYE_BLINK_BOT    90   /* blink: black arc bottom edge */
956	#define OEYE_HAPPY_BOT    115  /* happy: lower lid pushed up */
