958	/****************************************************************************
959	 * Name: draw_oeye_bg
960	 *
961	 * Description:
962	 *   Full-screen white fill.  Call ONCE per panel before the
963	 *   expression loop.  Never called again during the loop.
964	 *
965	 ****************************************************************************/
966	
967	static void draw_oeye_bg(void)
968	{
969	  lcd_fill_rect(0, 0, LCD_WIDTH - 1, LCD_HEIGHT - 1, OEYE_BG);
970	}
