972	/****************************************************************************
973	 * Name: draw_oeye_content
974	 *
975	 * Description:
976	 *   Redraw only the iris bounding box: clear box to white, then
977	 *   draw blue iris + black pupil + two highlights.  This is the
978	 *   fast per-frame content update — no full-screen fill.
979	 *
980	 ****************************************************************************/
981	
982	static void draw_oeye_content(void)
983	{
984	  /* Clear iris box to white (erases previous pupil/highlight/lid) */
985	
986	  lcd_fill_rect(OEYE_BOX_L, OEYE_BOX_T, OEYE_BOX_R, OEYE_BOX_B,
987	                OEYE_BG);
988	
989	  /* Blue iris */
990	
991	  lcd_fill_circle(80, 80, OEYE_IRIS_R, OEYE_IRIS);
992	
993	  /* Black pupil */
994	
995	  lcd_fill_circle(80, 80, OEYE_PUPIL_R, OEYE_PUPIL);
996	
997	  /* Two white highlights */
998	
999	  lcd_fill_circle(OEYE_HL1_X, OEYE_HL1_Y, OEYE_HL1_R, OEYE_HL);
1000	  lcd_fill_circle(OEYE_HL2_X, OEYE_HL2_Y, OEYE_HL2_R, OEYE_HL);
1001	}
