1003	/****************************************************************************
1004	 * Name: eye_o_neutral
1005	 *
1006	 * Description:
1007	 *   Neutral / fully open: redraw iris content + thin black eyelid
1008	 *   strips top and bottom.  The strips are outside the iris box
1009	 *   (y 0..16 and 143..159) so they overwrite the white bg there.
1010	 *
1011	 ****************************************************************************/
1012	
1013	static void eye_o_neutral(void)
1014	{
1015	  draw_oeye_content();
1016	
1017	  /* Upper eyelid: thin black strip at top */
1018	
1019	  lcd_fill_rect(0, 0, LCD_WIDTH - 1, OEYE_NEUTRAL_TOP, OEYE_LID);
1020	
1021	  /* Lower eyelid: thin black strip at bottom */
1022	
1023	  lcd_fill_rect(0, OEYE_NEUTRAL_BOT, LCD_WIDTH - 1, LCD_HEIGHT - 1,
1024	                OEYE_LID);
1025	}
