1027	/****************************************************************************
1028	 * Name: eye_o_half
1029	 *
1030	 * Description:
1031	 *   Half-closed: redraw iris content + wider black eyelid strips.
1032	 *   Upper lid extends into the iris box (y 0..50), lower lid
1033	 *   extends into the iris box (y 110..159).
1034	 *
1035	 ****************************************************************************/
1036	
1037	static void eye_o_half(void)
1038	{
1039	  draw_oeye_content();
1040	
1041	  /* Upper eyelid: covers top portion of iris (extends into box) */
1042	
1043	  lcd_fill_rect(0, 0, LCD_WIDTH - 1, OEYE_HALF_TOP, OEYE_LID);
