1045	  /* Lower eyelid: covers bottom portion (extends into box) */
1046	
1047	  lcd_fill_rect(0, OEYE_HALF_BOT, LCD_WIDTH - 1, LCD_HEIGHT - 1,
1048	                OEYE_LID);
