1051	/****************************************************************************
1052	 * Name: eye_o_blink
1053	 *
1054	 * Description:
1055	 *   Fully closed: clear iris box to white + draw thick black band
1056	 *   y70..90.  Also restore any previous eyelid strips outside the
1057	 *   box (top/bottom) back to white so only the black arc remains.
1058	 *
1059	 ****************************************************************************/
1060	
1061	static void eye_o_blink(void)
1062	{
1063	  /* Clear iris box to white */
1064	
1065	  lcd_fill_rect(OEYE_BOX_L, OEYE_BOX_T, OEYE_BOX_R, OEYE_BOX_B,
1066	                OEYE_BG);
1067	
1068	  /* Restore top/bottom strips outside box to white
1069	   * (removes leftover black eyelid from previous frame)
1070	   */
1071	
1072	  lcd_fill_rect(0, 0, LCD_WIDTH - 1, OEYE_BOX_T - 1, OEYE_BG);
1073	  lcd_fill_rect(0, OEYE_BOX_B + 1, LCD_WIDTH - 1, LCD_HEIGHT - 1,
1074	                OEYE_BG);
1075	
1076	  /* Black arc: thick band across the middle of the iris box */
1077	
1078	  lcd_fill_rect(OEYE_BOX_L, OEYE_BLINK_TOP, OEYE_BOX_R, OEYE_BLINK_BOT,
1079	                OEYE_LID);
