1082	/****************************************************************************
1083	 * Name: eye_o_happy
1084	 *
1085	 * Description:
1086	 *   Happy: redraw iris content + thin top lid + lower lid pushed
1087	 *   up to y=115 (smile arc).  Lower lid extends into the iris box.
1088	 *
1089	 ****************************************************************************/
1090	
1091	static void eye_o_happy(void)
1092	{
1093	  draw_oeye_content();
1094	
1095	  /* Upper eyelid: thin strip (same as neutral) */
1096	
1097	  lcd_fill_rect(0, 0, LCD_WIDTH - 1, OEYE_NEUTRAL_TOP, OEYE_LID);
1098	
1099	  /* Lower eyelid: push up to carve a smile arc */
1100	
1101	  lcd_fill_rect(0, OEYE_HAPPY_BOT, LCD_WIDTH - 1, LCD_HEIGHT - 1,
1102	                OEYE_LID);
1103	}
1104	
1105	/****************************************************************************
1106	 * Smooth blink animation — incremental eyelid sweep
1107	 *
1108	 * Instead of jumping neutral → half → blink in 3 big frames, the eyelids
1109	 * sweep in ~10-12 small steps.  Each step only draws a narrow black band
1110	 * (closing) or redraws the revealed eye content (opening), so the per-step
1111	 * pixel count is tiny — even bit-bang can do it smoothly.
1112	 *
1113	 *   Closing: top lid descends from OEYE_NEUTRAL_TOP → OEYE_BLINK_TOP,
1114	 *            bottom lid ascends from OEYE_NEUTRAL_BOT → OEYE_BLINK_BOT.
1115	 *   Opening: reverse.
1116	 ****************************************************************************/
1117	
1118	#define OEYE_BLINK_STEPS  10  /* number of animation sub-frames */
1119	
1120	/****************************************************************************
1121	 * Name: oeye_pixel_color
1122	 *
1123	 * Description:
1124	 *   Return the RGB565 color for pixel (px, py) in the eye content.
1125	 *   Checks highlight, pupil, iris, then falls back to background.
1126	 *
1127	 ****************************************************************************/
1128	
1129	static inline uint16_t oeye_pixel_color(int16_t px, int16_t py)
1130	{
1131	  int16_t ddx;
1132	  int16_t ddy;
1133	  int32_t d2;
1134	
1135	  /* Highlight 1 */
1136	
1137	  ddx = px - OEYE_HL1_X;
1138	  ddy = py - OEYE_HL1_Y;
1139	
1140	  if ((int32_t)ddx * ddx + (int32_t)ddy * ddy <=
1141	      (int32_t)OEYE_HL1_R * OEYE_HL1_R)
1142	    {
1143	      return OEYE_HL;
1144	    }
1145	
1146	  /* Highlight 2 */
1147	
1148	  ddx = px - OEYE_HL2_X;
1149	  ddy = py - OEYE_HL2_Y;
1150	
1151	  if ((int32_t)ddx * ddx + (int32_t)ddy * ddy <=
1152	      (int32_t)OEYE_HL2_R * OEYE_HL2_R)
1153	    {
1154	      return OEYE_HL;
1155	    }
1156	
1157	  /* Pupil */
1158	
1159	  ddx = px - 80;
1160	  ddy = py - 80;
1161	  d2 = (int32_t)ddx * ddx + (int32_t)ddy * ddy;
1162	
1163	  if (d2 <= (int32_t)OEYE_PUPIL_R * OEYE_PUPIL_R)
1164	    {
1165	      return OEYE_PUPIL;
1166	    }
1167	
1168	  /* Iris */
1169	
1170	  if (d2 <= (int32_t)OEYE_IRIS_R * OEYE_IRIS_R)
1171	    {
1172	      return OEYE_IRIS;
1173	    }
1174	
1175	  return OEYE_BG;
1176	}
1177	
1178	/****************************************************************************
1179	 * Name: oeye_draw_row_band
1180	 *
1181	 * Description:
1182	 *   Draw eye content (iris/pupil/highlights/bg) for rows y0..y1,
1183	 *   clipped to the iris bounding box X range.  Uses CASET/RASET once
1184	 *   and streams pixels row by row — much faster than lcd_fill_circle
1185	 *   per row.
1186	 *
1187	 ****************************************************************************/
1188	
1189	static void oeye_draw_row_band(int16_t y0, int16_t y1)
1190	{
1191	  uint8_t ca[4];
1192	  uint8_t ra[4];
1193	  uint8_t cmd[2];
1194	  int16_t x;
1195	  int16_t y;
1196	  int16_t x0 = OEYE_BOX_L;
1197	  int16_t x1 = OEYE_BOX_R;
1198	
1199	  /* CASET + RASET for the band */
1200	
1201	  ca[0] = (x0 >> 8) & 0xff;
1202	  ca[1] = x0 & 0xff;
1203	  ca[2] = (x1 >> 8) & 0xff;
1204	  ca[3] = x1 & 0xff;
1205	  lcd_send_cmd_data(0x2a, ca, 4);
1206	
1207	  ra[0] = (y0 >> 8) & 0xff;
1208	  ra[1] = y0 & 0xff;
1209	  ra[2] = (y1 >> 8) & 0xff;
1210	  ra[3] = y1 & 0xff;
1211	  lcd_send_cmd_data(0x2b, ra, 4);
1212	
1213	  /* RAMWR — stream pixels row by row */
1214	
1215	  lcd_send_cmd(0x2c);
1216	  gpio_write_fast(&g_cache_dc, 1);
1217	  gpio_write_fast(&g_cache_cs, 0);
1218	
1219	  for (y = y0; y <= y1; y++)
1220	    {
1221	      for (x = x0; x <= x1; x++)
1222	        {
1223	          uint16_t c = oeye_pixel_color(x, y);
1224	
1225	          cmd[0] = (c >> 8) & 0xff;
1226	          cmd[1] = c & 0xff;
1227	          spi_write_byte(cmd[0]);
1228	          spi_write_byte(cmd[1]);
1229	        }
1230	    }
1231	
1232	  gpio_write_fast(&g_cache_cs, 1);
1233	}
1234	
1235	/****************************************************************************
1236	 * Name: eye_o_blink_anim
1237	 *
1238	 * Description:
1239	 *   Smooth eyelid animation: close → brief hold → open.
1240	 *   Each step draws only the narrow newly-occluded/revealed strip,
1241	 *   so the per-step pixel count is small (160×~6px for 10 steps).
1242	 *
1243	 ****************************************************************************/
1244	
1245	static void eye_o_blink_anim(void)
1246	{
1247	  int step;
1248	  int16_t top_prev;
1249	  int16_t top_cur;
1250	  int16_t bot_prev;
1251	  int16_t bot_cur;
1252	
1253	  /* --- Phase 1: close (top lid descends, bottom lid ascends) --- */
1254	
1255	  top_prev = OEYE_NEUTRAL_TOP;
1256	  bot_prev = OEYE_NEUTRAL_BOT;
1257	
1258	  for (step = 1; step <= OEYE_BLINK_STEPS; step++)
1259	    {
1260	      /* Interpolate lid positions */
1261	
1262	      top_cur = OEYE_NEUTRAL_TOP +
1263	                (int16_t)((int32_t)(OEYE_BLINK_TOP - OEYE_NEUTRAL_TOP) *
1264	                          step / OEYE_BLINK_STEPS);
1265	      bot_cur = OEYE_NEUTRAL_BOT +
1266	                (int16_t)((int32_t)(OEYE_BLINK_BOT - OEYE_NEUTRAL_BOT) *
1267	                          step / OEYE_BLINK_STEPS);
1268	
1269	      /* Draw newly covered rows as black (only the delta strip) */
1270	
1271	      if (top_cur > top_prev)
1272	        {
1273	          lcd_fill_rect(OEYE_BOX_L, top_prev + 1,
1274	                        OEYE_BOX_R, top_cur, OEYE_LID);
1275	        }
1276	
1277	      if (bot_cur < bot_prev)
1278	        {
1279	          lcd_fill_rect(OEYE_BOX_L, bot_cur,
1280	                        OEYE_BOX_R, bot_prev - 1, OEYE_LID);
1281	        }
1282	
1283	      top_prev = top_cur;
1284	      bot_prev = bot_cur;
1285	    }
1286	
1287	  /* --- Phase 2: brief hold at fully closed --- */
1288	
1289	  up_mdelay(60);
1290	
1291	  /* --- Phase 3: open (top lid ascends, bottom lid descends) --- */
1292	
1293	  for (step = OEYE_BLINK_STEPS - 1; step >= 0; step--)
1294	    {
1295	      top_cur = OEYE_NEUTRAL_TOP +
1296	                (int16_t)((int32_t)(OEYE_BLINK_TOP - OEYE_NEUTRAL_TOP) *
1297	                          step / OEYE_BLINK_STEPS);
1298	      bot_cur = OEYE_NEUTRAL_BOT +
1299	                (int16_t)((int32_t)(OEYE_BLINK_BOT - OEYE_NEUTRAL_BOT) *
1300	                          step / OEYE_BLINK_STEPS);
1301	
1302	      /* Redraw revealed rows with eye content (only the delta strip) */
1303	
1304	      if (top_cur < top_prev)
1305	        {
1306	          oeye_draw_row_band(top_cur + 1, top_prev);
1307	        }
1308	
1309	      if (bot_cur > bot_prev)
1310	        {
1311	          oeye_draw_row_band(bot_prev, bot_cur - 1);
1312	        }
1313	
1314	      top_prev = top_cur;
1315	      bot_prev = bot_cur;
1316	    }
1317	
1318	  /* Restore the thin neutral eyelid strips (outside iris box) */
1319	
1320	  lcd_fill_rect(0, 0, LCD_WIDTH - 1, OEYE_NEUTRAL_TOP, OEYE_LID);
1321	  lcd_fill_rect(0, OEYE_NEUTRAL_BOT, LCD_WIDTH - 1, LCD_HEIGHT - 1,
1322	                OEYE_LID);
1323	}
