1325	/****************************************************************************
1326	 * Name: lcdtest_is_dvp_reserved_pin
1327	 *
1328	 * Description:
1329	 *   Check if a GPIO pin is in the DVP camera pin range (P29–P39).
1330	 *   These pins must never be driven by lcdtest GPIO loops because
1331	 *   they are routed to the GC2145 camera connector on the contest
1332	 *   board.  Driving them could damage the sensor or cause bus
1333	 *   contention.
1334	 *
1335	 *   Also protects SWD pins (P20, P21) and UART0 (P10, P11) as a
1336	 *   convenience — callers still check these explicitly for clarity.
1337	 *
1338	 ****************************************************************************/
1339	
1340	static bool lcdtest_is_dvp_reserved_pin(int pin)
1341	{
1342	  /* DVP camera connector: P29 through P39 inclusive.
1343	   * This range covers DVP_VS, DVP_HS, DVP_PCLK, DVP_MCLK,
1344	   * DVP_D[0:7], DVP_PWDNB, DVP_RST (depending on board routing).
1345	   */
1346	
1347	  if (pin >= 29 && pin <= 39)
1348	    {
1349	      return true;
1350	    }
1351	
1352	  return false;
1353	}
1354	
1355	/****************************************************************************
1356	 * Name: lcdtest_stages
1357	 *
1358	 * Description:
1359	 *   Staged LCD bring-up: A=backlight, B=init, C=40x40 red square.
1360	 *
1361	 ****************************************************************************/
1362	
1363	static int lcdtest_stages(void)
1364	{
1365	  /* --- Stage A: power + backlight --- */
1366	
1367	  syslog(LOG_INFO,
1368	         "[lcdtest] Stage A: LDO_3V3 ON (P52) + backlight ON (P25)\n");
1369	
1370	  gpio_set_output(LCD_PIN_LDO33_EN);
1371	  gpio_write(LCD_PIN_LDO33_EN, 1);
1372	  up_mdelay(50);   /* wait for LDO output to stabilize */
1373	
