1441	/****************************************************************************
1442	 * Name: lcdtest_scan
1443	 *
1444	 * Description:
1445	 *   Scan GPIO 0-47 for the LCD power enable pin.
1446	 *   Strategy: cumulative — pull each pin high and leave it high, so that
1447	 *   if multiple pins need to be high simultaneously the condition is met.
1448	 *   P25 (backlight) is held high throughout.  UART console pins (10, 11)
1449	 *   and LCD signal pins (2-5, 29) are skipped to keep the console and
1450	 *   SPI bus alive.
1451	 *
1452	 ****************************************************************************/
1453	
1454	static int lcdtest_scan(void)
1455	{
1456	  int pin;
1457	
1458	#ifdef CONFIG_EXAMPLES_GC2145_ID
1459	  if (bk7258_camera_dvp_active())
1460	    {
1461	      syslog(LOG_ERR,
1462	             "[lcdtest] refused: DVP pins P29-P39 are in use, "
1463	             "run 'camera stop' first\n");
1464	      return -EBUSY;
1465	    }
1466	#endif
1467	
1468	  /* Backlight on first */
1469	
1470	  gpio_set_output(LCD_PIN_BL);
1471	  gpio_write(LCD_PIN_BL, 1);
1472	
1473	  syslog(LOG_INFO,
1474	         "[scan] backlight P25 high, scanning GPIO 0-47 ...\n");
1475	
1476	  for (pin = 0; pin <= 47; pin++)
1477	    {
1478	      /* Skip UART0 console: RX=10, TX=11 */
1479	
1480	      if (pin == 10 || pin == 11)
1481	        {
1482	          syslog(LOG_INFO,
1483	                 "[scan] pin=%d skipped (UART0 console)\n", pin);
1484	          continue;
1485	        }
1486	
1487	      /* Skip LCD signal pins (both eyes + backlight) */
1488	
1489	      if (pin == g_lcd_left.sclk  || pin == g_lcd_left.cs  ||
1490	          pin == g_lcd_left.mosi  || pin == g_lcd_left.dc  ||
1491	          pin == g_lcd_left.rst   ||
1492	          pin == g_lcd_right.sclk || pin == g_lcd_right.cs ||
1493	          pin == g_lcd_right.mosi || pin == g_lcd_right.dc ||
1494	          pin == g_lcd_right.rst  ||
1495	          pin == LCD_PIN_BL)
1496	        {
1497	          syslog(LOG_INFO,
1498	                 "[scan] pin=%d skipped (LCD signal)\n", pin);
1499	          continue;
1500	        }
1501	
1502	      /* Skip SWD debug port: SWCLK=20, SWDIO=21 */
1503	
1504	      if (pin == 20 || pin == 21)
1505	        {
1506	          syslog(LOG_INFO,
1507	                 "[scan] pin=%d skipped (SWD debug)\n", pin);
1508	          continue;
1509	        }
1510	
1511	      /* Skip DVP camera connector: P29–P39 */
1512	
1513	      if (lcdtest_is_dvp_reserved_pin(pin))
1514	        {
1515	          syslog(LOG_INFO,
1516	                 "[scan] pin=%d skipped (DVP camera reserved)\n", pin);
1517	          continue;
1518	        }
1519	
1520	      gpio_set_output(pin);
1521	      gpio_write(pin, 1);
1522	      up_mdelay(800);
1523	
1524	      syslog(LOG_INFO, "[scan] pin=%d high\n", pin);
1525	    }
1526	
1527	  syslog(LOG_INFO,
1528	         "[scan] done - check screen for any change\n");
1529	
1530	  return OK;
1531	}
