1533	/****************************************************************************
1534	 * Name: lcdtest_pwr
1535	 *
1536	 * Description:
1537	 *   Full power-on sequence with configurable GPIO range for binary-search
1538	 *   identification of the LCD power enable pin.
1539	 *
1540	 *   Usage: lcdtest pwr [lo] [hi]
1541	 *     lo..hi  — decimal GPIO range to drive high (default 0..52)
1542	 *
1543	 *   Always skips: 2,3,4,5,25,29 (LCD)  10,11 (UART)  7,8 (motor)
1544	 *                 20,21 (SWD)  38,39 (LEDs)
1545	 *
1546	 ****************************************************************************/
1547	
1548	static int lcdtest_pwr(int lo, int hi)
1549	{
1550	  int pin;
1551	  int count = 0;
1552	  int off = 0;
1553	  char pinbuf[256];
1554	
1555	#ifdef CONFIG_EXAMPLES_GC2145_ID
1556	  if (bk7258_camera_dvp_active())
1557	    {
1558	      syslog(LOG_ERR,
1559	             "[lcdtest] refused: DVP pins P29-P39 are in use, "
1560	             "run 'camera stop' first\n");
1561	      return -EBUSY;
1562	    }
1563	#endif
1564	
1565	  /* Step 1: drive GPIO lo..hi high, skip reserved pins.
1566	   * Collect the actual pin list for the syslog dump.
1567	   */
1568	
1569	  syslog(LOG_INFO,
1570	         "[pwr] step1: GPIO %d-%d high (skip reserved)\n",
1571	         lo, hi);
1572	
1573	  for (pin = lo; pin <= hi; pin++)
1574	    {
1575	      /* LCD signals (both eyes) */
1576	
1577	      if (pin == 2 || pin == 3 || pin == 4 || pin == 5 ||
1578	          pin == 6 || pin == 7 || pin == 22 || pin == 23 ||
1579	          pin == 24 || pin == 25 || pin == 45)
1580	        {
1581	          continue;
1582	        }
1583	
1584	      /* UART0 console */
1585	
1586	      if (pin == 10 || pin == 11)
1587	        {
1588	          continue;
1589	        }
1590	
1591	      /* Vibration motor (P7 is right-eye DC, only skip P8) */
1592	
1593	      if (pin == 8)
1594	        {
1595	          continue;
1596	        }
1597	
1598	      /* Indicator LEDs */
1599	
1600	      if (pin == 38 || pin == 39)
1601	        {
1602	          continue;
1603	        }
1604	
1605	      /* SWD debug port: SWCLK=20, SWDIO=21 */
1606	
1607	      if (pin == 20 || pin == 21)
1608	        {
1609	          continue;
1610	        }
1611	
1612	      /* DVP camera connector: P29–P39 */
1613	
1614	      if (lcdtest_is_dvp_reserved_pin(pin))
1615	        {
1616	          continue;
1617	        }
1618	
1619	      gpio_set_output(pin);
1620	      gpio_write(pin, 1);
1621	      count++;
1622	
1623	      if (off < (int)sizeof(pinbuf) - 8)
1624	        {
1625	          off += snprintf(pinbuf + off, sizeof(pinbuf) - off,
1626	                          " %d", pin);
1627	        }
1628	    }
1629	
1630	  pinbuf[off] = '\0';
1631	
1632	  /* Print which pins were actually driven high */
1633	
1634	  syslog(LOG_INFO,
1635	         "[pwr] driven high (%d pins):%s\n", count, pinbuf);
1636	
1637	  /* Step 2: wait for power rails to settle */
1638	
1639	  syslog(LOG_INFO, "[pwr] step2: wait 50 ms ...\n");
1640	  up_mdelay(50);
1641	
1642	  /* Step 3: backlight on */
1643	
1644	  syslog(LOG_INFO, "[pwr] step3: backlight P25 high\n");
1645	  gpio_set_output(LCD_PIN_BL);
1646	  gpio_write(LCD_PIN_BL, 1);
1647	
1648	  /* Step 4: setup left-eye SPI pins + hardware reset */
1649	
1650	  syslog(LOG_INFO,
1651	         "[pwr] step4: left SPI setup + RST low 15 ms then high\n");
1652	  lcd_setup_pins(&g_lcd_left);
1653	  gpio_write(g_active_pins->rst, 0);
1654	  up_mdelay(15);
1655	  gpio_write(g_active_pins->rst, 1);
1656	  up_mdelay(120);
1657	
1658	  /* Step 5: GC9D01 init sequence */
1659	
1660	  syslog(LOG_INFO, "[pwr] step5: GC9D01 init sequence\n");
1661	  lcd_init_sequence(true);
1662	
1663	  /* Step 6: clear screen to black */
1664	
1665	  syslog(LOG_INFO, "[pwr] step6: fill screen black\n");
1666	  lcd_fill_rect(0, 0, LCD_WIDTH - 1, LCD_HEIGHT - 1, 0x0000);
1667	
1668	  /* Step 7: draw 40x40 red square at (60,60) */
1669	
1670	  syslog(LOG_INFO,
1671	         "[pwr] step7: fill 40x40 red at (60,60)\n");
1672	  lcd_fill_rect(60, 60,
1673	                60 + SQ_SIZE - 1, 60 + SQ_SIZE - 1,
1674	                0xf800);
1675	
1676	  syslog(LOG_INFO,
1677	         "[pwr] done (%d pins driven) - "
1678	         "screen should show red on black\n",
1679	         count);
1680	  return OK;
1681	}
