1830	  int gaze = 0;
1831	
1832	  /* --- Power-on (same as go step1-3) --- */
1833	
1834	  syslog(LOG_INFO,
1835	         "[anim] step1: GPIO 0-52 high (skip reserved)\n");
1836	
1837	  for (pin = 0; pin <= 52; pin++)
1838	    {
1839	      if (pin == 2 || pin == 3 || pin == 4 || pin == 5 ||
1840	          pin == 6 || pin == 7 || pin == 22 || pin == 23 ||
1841	          pin == 24 || pin == 25 || pin == 45)
1842	        {
1843	          continue;
1844	        }
1845	
1846	      if (pin == 10 || pin == 11 || pin == 8 ||
1847	          pin == 20 || pin == 21 ||
1848	          pin == 38 || pin == 39)
1849	        {
1850	          continue;
1851	        }
