2034	  lcd_display_on();
2035	
2036	  /* --- Expression loop: 2 rounds --- */
2037	
2038	  for (round = 0; round < 2; round++)
2039	    {
2040	      syslog(LOG_INFO, "[emo] round %d/2\n", round + 1);
2041	
2042	      /* neutral */
