2064	      eye_look(0);
2065	      lcd_set_pins(&g_lcd_right);
2066	      eye_look(0);
2067	      up_mdelay(600);
2068	
2069	      /* look right */
2070	
2071	      syslog(LOG_INFO, "[emo] look right\n");
2072	      lcd_set_pins(&g_lcd_left);
2073	      eye_look(22);
2074	      lcd_set_pins(&g_lcd_right);
2075	      eye_look(22);
2076	      up_mdelay(600);
2077	
2078	      /* happy */
2079	
2080	      syslog(LOG_INFO, "[emo] happy\n");
2081	      lcd_set_pins(&g_lcd_left);
2082	      eye_happy();
2083	      lcd_set_pins(&g_lcd_right);
2084	      eye_happy();
2085	      up_mdelay(1000);
2086	
2087	      /* TODO: eye_emo_blink disabled — bit-bang scanline blink
2088	       * looks blocky; enable after switching to QSPI.
2089	       */
2090	
2091	      /* neutral */
2092	
2093	      syslog(LOG_INFO, "[emo] neutral\n");
2094	      lcd_set_pins(&g_lcd_left);
2095	      eye_neutral();
2096	      lcd_set_pins(&g_lcd_right);
2097	      eye_neutral();
