2105	/****************************************************************************
2106	 * Name: lcdtest_hear
2107	 *
2108	 * Description:
2109	 *   Continuous sound localization loop.
2110	 *   LCD + audio_init once at start.  Then loop up to 300 iterations:
2111	 *     capture N=2048 → onset gate → locate → eye_look → print.
2112	 *   Exits on iteration cap or serial keypress.
2113	 *
2114	 ****************************************************************************/
2115	
2116	#define HEAR_LOOP_MAX    80    /* ~4-5 s at ~60 ms per iteration */
2117	#define HEAR_N_SAMPLES   2048
2118	#define HEAR_ONSET_GATE  80   /* RMS threshold to trigger locate */
2119	
2120	static int lcdtest_hear(void)
2121	{
2122	  int tau_q8;
2123	  int dx;
2124	  int iter;
2125	  int n;
2126	  int energy;
2127	  int pin;
2128	  int count = 0;
2129	
2130	  /* ---- Hardware bring-up (same as lcdtest_go steps 1-5,7,9-10,12
2131	   *       but WITHOUT draw_eye — we paint emo eyes directly).
2132	   * ---- Step 1: GPIO 0-52 high, skip reserved pins ---- */
2133	
2134	  for (pin = 0; pin <= 52; pin++)
2135	    {
2136	      if (pin == 2 || pin == 3 || pin == 4 || pin == 5 ||
2137	          pin == 6 || pin == 7 || pin == 22 || pin == 23 ||
2138	          pin == 24 || pin == 25 || pin == 45)
2139	        {
2140	          continue;
2141	        }
2142	
2143	      if (pin == 10 || pin == 11 || pin == 8 ||
2144	          pin == 20 || pin == 21 ||
2145	          pin == 38 || pin == 39)
2146	        {
2147	          continue;
2148	        }
2149	
2150	      /* DVP camera connector: P29–P39 */
2151	
2152	      if (lcdtest_is_dvp_reserved_pin(pin))
2153	        {
2154	          continue;
2155	        }
2156	
2157	      gpio_set_output(pin);
2158	      gpio_write(pin, 1);
2159	      count++;
2160	    }
2161	
2162	  /* Step 2: wait for power rails */
2163	
2164	  up_mdelay(500);
2165	
2166	  /* Step 3: backlight on */
2167	
2168	  gpio_set_output(LCD_PIN_BL);
2169	  gpio_write(LCD_PIN_BL, 1);
2170	
2171	  /* ---- Left eye: SPI pins + RST + init + display on ---- */
2172	
2173	  lcd_setup_pins(&g_lcd_left);
2174	  gpio_write(g_active_pins->rst, 0);
2175	  up_mdelay(15);
2176	  gpio_write(g_active_pins->rst, 1);
2177	  up_mdelay(120);
2178	  lcd_init_sequence(false);
2179	  lcd_display_on();
2180	
2181	  /* ---- Right eye: SPI pins + RST + init + display on ---- */
2182	
2183	  lcd_setup_pins(&g_lcd_right);
2184	  gpio_write(g_active_pins->rst, 0);
2185	  up_mdelay(15);
2186	  gpio_write(g_active_pins->rst, 1);
2187	  up_mdelay(120);
2188	  lcd_init_sequence(false);
2189	  lcd_display_on();
2190	
2191	  /* ---- Draw emo eyes (no round-eye flash) ---- */
2192	
2193	  lcd_set_pins(&g_lcd_left);
2194	  eye_neutral();
2195	  lcd_set_pins(&g_lcd_right);
2196	  eye_neutral();
2197	  lcd_set_pins(&g_lcd_left);
2198	
2199	  /* Initialize audio ADC (once) */
2200	
2201	  audio_init();
2202	
2203	  /* Suppress per-capture syslog during tight loop */
2204	
2205	  bk7258_mic_set_quiet(true);
2206	
2207	  syslog(LOG_INFO,
2208	         "[hear] === sound localization loop ===\n"
2209	         "[hear] loop_max=%d  N=%d  onset_gate=%d\n",
2210	         HEAR_LOOP_MAX, HEAR_N_SAMPLES, HEAR_ONSET_GATE);
2211	
2212	  for (iter = 0; iter < HEAR_LOOP_MAX; iter++)
2213	    {
2214	      /* Capture a chunk */
2215	
2216	      n = audio_capture(HEAR_N_SAMPLES);
2217	      if (n < 64)
2218	        {
2219	          continue;
2220	        }
2221	
2222	      /* Onset gate: check energy before running full locate */
2223	
2224	      energy = bk7258_mic_energy(n);
2225	      if (energy < HEAR_ONSET_GATE)
2226	        {
2227	          continue;
2228	        }
2229	
2230	      /* Sound detected — run full locate on this capture */
2231	
2232	      dx = mic_locate_process(n, &tau_q8);
2233	
2234	      syslog(LOG_INFO,
2235	             "[hear] iter=%d  energy=%d  dx=%d  "
2236	             "tau_q8=%d (%.2f samp)\n",
2237	             iter, energy, dx,
2238	             tau_q8, (double)tau_q8 / 256.0);
2239	
2240	      /* Drive eye toward detected direction (both panels) */
2241	
2242	      lcd_set_pins(&g_lcd_left);
2243	      eye_look(dx);
2244	      lcd_set_pins(&g_lcd_right);
2245	      eye_look(dx);
2246	      lcd_set_pins(&g_lcd_left);
2247	    }
2248	
2249	  /* Cleanup */
2250	
2251	  bk7258_mic_set_quiet(false);
2252	  audio_deinit();
2253	
2254	  syslog(LOG_INFO,
2255	         "[hear] loop ended after %d iterations\n", iter);
2256	
2257	  return OK;
2258	}
