2538	/****************************************************************************
2539	 * Name: bk7258_lcdtest_main
2540	 *
2541	 * Description:
2542	 *   NSH command "lcdtest":
2543	 *     lcdtest          — staged bring-up (A/B/C, diagnostics)
2544	 *     lcdtest go       — one-step dual-eye LCD bring-up
2545	 *     lcdtest anim     — pupil tracking animation (3 rounds)
2546	 *     lcdtest emo      — Cozmo/Vector expression eyes (2 rounds)
2547	 *     lcdtest oeye     — official-website-style eye preview
2548	 *     lcdtest blink [N] — smooth blink preview (default 5 blinks)
2549	 *     lcdtest hear     — sound localization → eye_look
2550	 *     lcdtest mic      — raw ADC capture + RMS dump
2551	 *     lcdtest pwr lo hi — power-on GPIO range for binary-search
2552	 *     lcdtest scan     — GPIO pin scan for LCD power enable
2553	 *
2554	 ****************************************************************************/
2555	
2556	int bk7258_lcdtest_main(int argc, char *argv[])
2557	{
2558	  if (argc > 1 && strcmp(argv[1], "go") == 0)
2559	    {
2560	      return lcdtest_go();
2561	    }
2562	
2563	  if (argc > 1 && strcmp(argv[1], "anim") == 0)
2564	    {
2565	      return lcdtest_anim();
2566	    }
2567	
2568	  if (argc > 1 && strcmp(argv[1], "emo") == 0)
2569	    {
2570	      return lcdtest_emo();
2571	    }
2572	
2573	  if (argc > 1 && strcmp(argv[1], "oeye") == 0)
2574	    {
2575	      return lcdtest_oeye();
2576	    }
2577	
2578	  if (argc > 1 && strcmp(argv[1], "blink") == 0)
2579	    {
2580	      int count = 5;
2581	
2582	      if (argc > 2)
2583	        {
2584	          count = atoi(argv[2]);
2585	        }
2586	
2587	      if (count < 1)
2588	        {
2589	          count = 1;
2590	        }
2591	
2592	      return lcdtest_blink(count);
2593	    }
2594	
2595	  if (argc > 1 && strcmp(argv[1], "scan") == 0)
2596	    {
2597	      return lcdtest_scan();
2598	    }
2599	
2600	  if (argc > 1 && strcmp(argv[1], "pwr") == 0)
2601	    {
2602	      int lo = 0;
2603	      int hi = 52;
2604	
2605	      if (argc > 2)
2606	        {
2607	          lo = atoi(argv[2]);
2608	        }
2609	
2610	      if (argc > 3)
2611	        {
2612	          hi = atoi(argv[3]);
2613	        }
2614	
2615	      if (lo < 0)
2616	        {
2617	          lo = 0;
2618	        }
2619	
2620	      if (hi > 52)
2621	        {
2622	          hi = 52;
2623	        }
2624	
2625	      if (lo > hi)
2626	        {
2627	          syslog(LOG_ERR,
2628	                 "[pwr] error: lo(%d) > hi(%d)\n", lo, hi);
2629	          return -EINVAL;
2630	        }
2631	
2632	      return lcdtest_pwr(lo, hi);
2633	    }
2634	
2635	  if (argc > 1 && strcmp(argv[1], "hear") == 0)
2636	    {
2637	      return lcdtest_hear();
2638	    }
2639	
2640	  if (argc > 1 && strcmp(argv[1], "mic") == 0)
2641	    {
2642	      return bk7258_mic_main(argc - 1, &argv[1]);
2643	    }
2644	
2645	  return lcdtest_stages();
2646	}
