static int lcd_spi_init(const lcd_pins_t *pins)
{
  uint32_t ctrl_val;
  uint32_t cfg_val;

  /* Only left screen (P2/P3/P4) maps to SPI1 */

  if (pins->sclk != 2 || pins->cs != 3 || pins->mosi != 4)
    {
      g_hw_spi_active = false;
      return -EINVAL;
    }

  /* Save current GPIO CFG for SPI1 pins so we can restore later */

  g_saved_cfg_sclk = getreg32(BK7258_GPIO_CFG(pins->sclk));
  g_saved_cfg_cs   = getreg32(BK7258_GPIO_CFG(pins->cs));
  g_saved_cfg_mosi = getreg32(BK7258_GPIO_CFG(pins->mosi));

  /* Enable SPI1 module clock (save register first for restore) */

  g_saved_sys_clk_en = getreg32(BK7258_SYS_CLK_ENABLE_REG);
  putreg32(g_saved_sys_clk_en | SPI1_CLK_ENABLE_BIT,
           BK7258_SYS_CLK_ENABLE_REG);

  /* Configure GPIO 2/3/4 for SPI1 function (function_select = 0) */

  gpio_set_second_func(pins->sclk, 0);
  gpio_set_second_func(pins->cs,   0);
  gpio_set_second_func(pins->mosi, 0);

  /* Soft-reset SPI1 */

  putreg32(SPI_SOFT_RESET, SPI_REG_GLOBAL_CTRL(BK7258_SPI1_BASE));
  putreg32(SPI_CLK_GATE_BYPASS, SPI_REG_GLOBAL_CTRL(BK7258_SPI1_BASE));

  /* Configure CTRL: master, SPI mode 0, 8-bit, MSB first, 60 MHz */

  ctrl_val = 0;
  ctrl_val |= SPI_CTRL_MASTER_BIT;        /* master mode */
  ctrl_val |= SPI_CTRL_ENABLE_BIT;        /* enable SPI */
  ctrl_val |= (SPI1_CLK_RATE << SPI_CTRL_CLK_RATE_SHIFT);
  /* CPOL=0, CPHA=0, bit_width=0 (8-bit), lsb_first=0 (MSB first) */

  putreg32(ctrl_val, SPI_REG_CTRL(BK7258_SPI1_BASE));

  /* Configure CFG: TX enable, RX disable */

  cfg_val = SPI_CFG_TX_EN_BIT;
  putreg32(cfg_val, SPI_REG_CFG(BK7258_SPI1_BASE));

  /* Clear FIFOs */

  putreg32(SPI_INT_TX_FIFO_CLR | SPI_INT_RX_FIFO_CLR,
           SPI_REG_INT_STATUS(BK7258_SPI1_BASE));

  g_hw_spi_active = true;

  syslog(LOG_INFO,
         "[lcd] SPI1 init: base=0x%08X clk_rate=%d (~%d MHz)\n",
         BK7258_SPI1_BASE, SPI1_CLK_RATE,
         120 / (SPI1_CLK_RATE + 1));

  return 0;
}

static void lcd_spi_deinit(void)
{
  if (!g_hw_spi_active)
    {
      return;
    }

  /* Disable SPI1 */

  putreg32(0, SPI_REG_CTRL(BK7258_SPI1_BASE));

  /* Restore GPIO CFG for SPI1 pins */

  gpio_restore_cfg(g_lcd_left.sclk, g_saved_cfg_sclk);
  gpio_restore_cfg(g_lcd_left.cs,   g_saved_cfg_cs);
  gpio_restore_cfg(g_lcd_left.mosi, g_saved_cfg_mosi);

  /* Restore SYS clock enable register (clear SPI1 bit only if we
   * set it — avoid clearing bits that were already on)
   */

  putreg32(g_saved_sys_clk_en, BK7258_SYS_CLK_ENABLE_REG);

  g_hw_spi_active = false;
}

/****************************************************************************
 * Name: lcd_spi_write
 *
 * Description:
 *   Write data bytes via hardware SPI1 peripheral.
 *   Polls TX FIFO ready flag for flow control.
 *   Handles transfers larger than 4095 bytes by chunking.
 *
 ****************************************************************************/

static void lcd_spi_write(const uint8_t *data, size_t len)
{
  size_t remaining = len;
  const uint8_t *p = data;

  while (remaining > 0)
    {
      size_t chunk = remaining;

      if (chunk > SPI_CFG_TX_TRANS_LEN_MASK)
        {
          chunk = SPI_CFG_TX_TRANS_LEN_MASK;
        }

      /* Set TX transfer length */

      uint32_t cfg_val = SPI_CFG_TX_EN_BIT |
                         (chunk << SPI_CFG_TX_TRANS_LEN_SHIFT);
      putreg32(cfg_val, SPI_REG_CFG(BK7258_SPI1_BASE));

      /* Clear TX FIFO */

      putreg32(SPI_INT_TX_FIFO_CLR,
               SPI_REG_INT_STATUS(BK7258_SPI1_BASE));

      /* Feed FIFO — write up to SPI_FIFO_DEPTH bytes, then poll */

      size_t sent = 0;

      while (sent < chunk)
        {
          /* Wait for TX FIFO write-ready */

          while (!(getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE)) &
                   SPI_INT_TX_FIFO_WR_READY))
            {
            }

          /* Write up to SPI_FIFO_DEPTH bytes in this burst */

          size_t burst = chunk - sent;

          if (burst > SPI_FIFO_DEPTH)
            {
              burst = SPI_FIFO_DEPTH;
            }

          size_t i;

          for (i = 0; i < burst; i++)
            {
              putreg32(p[sent + i], SPI_REG_DATA(BK7258_SPI1_BASE));
            }

          sent += burst;
        }

      /* Wait for transfer to complete — poll until TX FIFO is empty
       * and the SPI is idle.  The simplest approach: wait for
       * tx_fifo_wr_ready which indicates the FIFO has drained.
       */

      while (!(getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE)) &
               SPI_INT_TX_FIFO_WR_READY))
        {
        }

      /* Small delay to ensure last byte is clocked out on the wire */

      __asm__ volatile("nop; nop; nop; nop;");

      p += chunk;
      remaining -= chunk;
    }
}

#endif /* CONFIG_LCD_GC9D01_HW_SPI */

