  lcd_init_sequence(true);

  /* Fill black to confirm screen is alive */

  lcd_fill_rect(0, 0, LCD_WIDTH - 1, LCD_HEIGHT - 1, 0x0000);

  syslog(LOG_INFO,
         "[lcd] preview init done — screen should show black\n");

  return 0;
}

