473	/****************************************************************************
474	 * Name: lcd_spi_pins_to_spi / lcd_spi_pins_to_gpio
475	 *
476	 * Description:
477	 *   Switch SPI1 pins between SPI peripheral mode and GPIO output mode.
478	 *   In SPI mode, hardware drives SCLK/CS/MOSI for data transfers.
479	 *   In GPIO mode, bit-bang drives them for commands.
480	 *
481	 ****************************************************************************/
482	
483	static void lcd_spi_pins_to_spi(void)
484	{
485	  if (g_pins_in_spi_mode)
486	    {
487	      return;
488	    }
