499	static void lcd_spi_pins_to_gpio(void)
500	{
501	  if (!g_pins_in_spi_mode)
502	    {
503	      return;
504	    }
505	
506	  /* Restore P2/P3/P4 to GPIO output mode */
507	
508	  gpio_set_output_cached(g_lcd_left.sclk, &g_cache_sclk);
509	  gpio_set_output_cached(g_lcd_left.mosi, &g_cache_mosi);
510	  gpio_set_output_cached(g_lcd_left.cs,   &g_cache_cs);
511	
512	  g_pins_in_spi_mode = false;
513	}
