515	/****************************************************************************
516	 * Name: lcd_spi_write
517	 *
518	 * Description:
519	 *   Write data bytes via hardware SPI1 peripheral.
520	 *   Pins must be in SPI mode (call lcd_spi_pins_to_spi first).
521	 *   Polls TX FIFO ready flag for flow control.
522	 *   Handles transfers larger than 4095 bytes by chunking.
523	 *
524	 ****************************************************************************/
525	
526	static void lcd_spi_write(const uint8_t *data, size_t len)
527	{
528	  size_t remaining = len;
529	  const uint8_t *p = data;
530	
531	  while (remaining > 0)
532	    {
533	      size_t chunk = remaining;
534	
535	      if (chunk > SPI_CFG_TX_TRANS_LEN_MASK)
536	        {
537	          chunk = SPI_CFG_TX_TRANS_LEN_MASK;
538	        }
539	
540	      /* Set TX transfer length */
541	
542	      uint32_t cfg_val = SPI_CFG_TX_EN_BIT |
543	                         (chunk << SPI_CFG_TX_TRANS_LEN_SHIFT);
544	      putreg32(cfg_val, SPI_REG_CFG(BK7258_SPI1_BASE));
545	
546	      /* Clear TX FIFO */
547	
548	      putreg32(SPI_INT_TX_FIFO_CLR,
549	               SPI_REG_INT_STATUS(BK7258_SPI1_BASE));
550	
551	      /* Feed FIFO — write up to SPI_FIFO_DEPTH bytes, then poll */
552	
553	      size_t sent = 0;
554	
555	      while (sent < chunk)
556	        {
557	          /* Wait for TX FIFO write-ready */
558	
559	          while (!(getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE)) &
560	                   SPI_INT_TX_FIFO_WR_READY))
561	            {
562	            }
563	
564	          /* Write up to SPI_FIFO_DEPTH bytes in this burst */
565	
566	          size_t burst = chunk - sent;
567	
568	          if (burst > SPI_FIFO_DEPTH)
569	            {
570	              burst = SPI_FIFO_DEPTH;
571	            }
572	
573	          size_t i;
574	
575	          for (i = 0; i < burst; i++)
576	            {
577	              putreg32(p[sent + i], SPI_REG_DATA(BK7258_SPI1_BASE));
578	            }
579	
580	          sent += burst;
581	        }
582	
583	      /* Wait for transfer to complete */
584	
585	      while (!(getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE)) &
586	               SPI_INT_TX_FIFO_WR_READY))
587	        {
588	        }
589	
590	      /* Small delay to ensure last byte is clocked out */
591	
592	      __asm__ volatile("nop; nop; nop; nop;");
593	
594	      p += chunk;

595	      remaining -= chunk;
596	    }
597	}
