638	/****************************************************************************
639	 * Name: spi_write_byte
640	 *
641	 * Description:
642	 *   Bit-bang one byte, MSB-first, SPI mode 0.
643	 *   Uses cached GPIO values (no getreg32 read) and no NOP delay.
644	 *   GC9D01 can handle fast SPI clock; add back one spi_delay() if
645	 *   display shows corruption.
646	 *
647	 ****************************************************************************/
648	
649	static void spi_write_byte(uint8_t byte)
650	{
651	  int bit;
652	
653	  for (bit = 7; bit >= 0; bit--)
654	    {
655	      gpio_write_fast(&g_cache_mosi, (byte >> bit) & 1);
656	      gpio_write_fast(&g_cache_sclk, 1);
657	      gpio_write_fast(&g_cache_sclk, 0);
658	    }
659	}
