661	/****************************************************************************
662	 * Name: lcd_send_cmd / lcd_send_data / lcd_send_cmd_data
663	 ****************************************************************************/
664	
665	static void lcd_send_cmd(uint8_t cmd)
666	{
667	#ifdef CONFIG_LCD_GC9D01_HW_SPI
668	  /* Commands always use bit-bang — ensure GPIO mode */
669	
670	  if (g_hw_spi_capable)
671	    {
672	      lcd_spi_pins_to_gpio();
673	    }
674	#endif
675	
676	  gpio_write_fast(&g_cache_dc, 0);
677	  gpio_write_fast(&g_cache_cs, 0);
678	  spi_write_byte(cmd);
679	  gpio_write_fast(&g_cache_cs, 1);
680	}
681	
682	static void lcd_send_data(const uint8_t *data, int len)
683	{
684	#ifdef CONFIG_LCD_GC9D01_HW_SPI
685	  /* Use hardware SPI for data when available (left screen) */
686	
687	  if (g_hw_spi_capable)
688	    {
689	      gpio_write_fast(&g_cache_dc, 1);
690	      gpio_write_fast(&g_cache_cs, 0);
691	      lcd_spi_pins_to_spi();
692	      lcd_spi_write(data, len);
693	      lcd_spi_pins_to_gpio();
694	      gpio_write_fast(&g_cache_cs, 1);

695	      return;
696	    }
697	#endif
698	
699	  /* Bit-bang fallback */
700	
701	  int i;
702	
703	  gpio_write_fast(&g_cache_dc, 1);
704	  gpio_write_fast(&g_cache_cs, 0);
705	  for (i = 0; i < len; i++)
706	    {
707	      spi_write_byte(data[i]);
708	    }
709	
710	  gpio_write_fast(&g_cache_cs, 1);
711	}
712	
713	static void lcd_send_cmd_data(uint8_t cmd, const uint8_t *data, int len)
714	{
715	  lcd_send_cmd(cmd);
716	  if (len > 0)
717	    {
718	      lcd_send_data(data, len);
719	    }
720	}
