361	{
362		uint8_t data = 0;
363		uint32_t offset = s_spi[id].rx_offset;
364	
365		while (spi_hal_read_byte(&s_spi[id].hal, &data) == BK_OK) {
366			if ((s_spi[id].rx_buf) && (offset < s_spi[id].rx_size)) {
367				s_spi[id].rx_buf[offset++] = data;
368			}
369		}
370		s_spi[id].rx_offset = offset;
371		SPI_LOGV("spi offset:%d\r\n", s_spi[id].rx_offset);
372		return offset;
373	}
