174	/****************************************************************************
175	 * Name: gpio_set_output_cached
176	 *
177	 * Description:
178	 *   Configure pin as GPIO output and cache the CFG register values
179	 *   for fast putreg32-only writes (no getreg32 read needed later).
180	 *
181	 ****************************************************************************/
182	
183	static void gpio_set_output_cached(int pin, gpio_cache_t *c)
184	{
185	  uint32_t cfg;
186	
187	  c->addr = BK7258_GPIO_CFG(pin);
188	  cfg = getreg32(c->addr);
189	  cfg &= ~GPIO_CFG_SECOND_FUNC;
190	  cfg &= ~GPIO_CFG_OUTPUT_EN;
191	  cfg &= ~GPIO_CFG_INPUT_EN;
192	  cfg &= ~GPIO_CFG_OUTPUT;   /* output = 0 */
193	  putreg32(cfg, c->addr);
194	  c->base_lo = cfg;            /* OUTPUT=0 */
195	  c->base_hi = cfg | GPIO_CFG_OUTPUT; /* OUTPUT=1 */
196	}
