/****************************************************************************
 * Name: gpio_set_second_func
 *
 * Description:
 *   Configure a GPIO pin for peripheral (second) function.
 *
 ****************************************************************************/

#ifdef CONFIG_LCD_GC9D01_HW_SPI

static void gpio_set_second_func(int pin, int func_sel)
{
  uint32_t cfg;
  uintptr_t func_reg;
  uint32_t shift;
  uint32_t val;

  cfg = getreg32(BK7258_GPIO_CFG(pin));
  cfg |= GPIO_CFG_SECOND_FUNC;    /* second function mode */
  cfg |= GPIO_CFG_OUTPUT_EN;      /* disable output (active-low) */
  cfg &= ~GPIO_CFG_INPUT_EN;      /* disable input */
  cfg &= ~GPIO_CFG_PULL_EN;       /* disable pull */
  putreg32(cfg, BK7258_GPIO_CFG(pin));

  func_reg = BK7258_SYS_GPIO_FUNC(pin);
  shift = BK7258_GPIO_FUNC_SHIFT(pin);
  val = getreg32(func_reg);
  val &= ~(BK7258_GPIO_FUNC_MASK << shift);
  val |= ((uint32_t)(func_sel & BK7258_GPIO_FUNC_MASK) << shift);
  putreg32(val, func_reg);
}

/****************************************************************************
 * Name: lcd_spi_init
 *
 * Description:
 *   Initialize BK7258 SPI1 for left-screen LCD data transfers.
 *   Returns 0 on success, negative errno on failure.
 *   On failure, g_hw_spi_capable stays false — caller falls back to bit-bang.
 *
 *   Init sequence (matching ARMino spi_ll_init + spi_hal_configure):
 *     1. Enable SPI1 module clock, verify by read-back
 *     2. Set CLK_GATE_BYPASS (keep clock running during reset)
 *     3. Soft-reset
 *     4. Configure CTRL: master, mode 0, 8-bit, MSB first, byte_interval=1
 *     5. Configure CFG: TX enable
 *     6. Clear FIFOs
 *
 ****************************************************************************/

static int lcd_spi_init(const lcd_pins_t *pins)
{
  uint32_t ctrl_val;
  uint32_t cfg_val;
  uint32_t readback;

  if (pins->sclk != 2 || pins->cs != 3 || pins->mosi != 4)
    {
      g_hw_spi_capable = false;
      return -EINVAL;
    }

  /* Step 1: Enable SPI1 module clock, verify by read-back */

  g_saved_sys_clk_en = getreg32(BK7258_SYS_CLK_ENABLE_REG);
  putreg32(g_saved_sys_clk_en | SPI1_CLK_ENABLE_BIT,
           BK7258_SYS_CLK_ENABLE_REG);

  readback = getreg32(BK7258_SYS_CLK_ENABLE_REG);

  if (!(readback & SPI1_CLK_ENABLE_BIT))
    {
      syslog(LOG_ERR,
             "[lcd] SPI1 clock enable FAILED: wrote 0x%08lx, "
             "read 0x%08lx\n",
             (unsigned long)(g_saved_sys_clk_en | SPI1_CLK_ENABLE_BIT),
             (unsigned long)readback);
      g_hw_spi_capable = false;
      return -EIO;
    }

  /* Step 2: CLK_GATE_BYPASS first (ARMino: keep clock alive during reset) */

  putreg32(SPI_CLK_GATE_BYPASS, SPI_REG_GLOBAL_CTRL(BK7258_SPI1_BASE));

  /* Step 3: Soft-reset, then re-assert bypass */

  putreg32(SPI_SOFT_RESET, SPI_REG_GLOBAL_CTRL(BK7258_SPI1_BASE));
  putreg32(SPI_CLK_GATE_BYPASS, SPI_REG_GLOBAL_CTRL(BK7258_SPI1_BASE));

  /* Step 4: Configure CTRL
   *   master=1, enable=1, 8-bit, MSB first, CPOL=0, CPHA=0
   *   byte_interval=1 (required for BK7258 per spi_ll.h comment)
   *   clk_rate=0 → 26 MHz (XTAL source, no divider)
   */

  ctrl_val = SPI_CTRL_MASTER_BIT |
             SPI_CTRL_ENABLE_BIT |
             (1u << SPI_CTRL_BYTE_INTERVAL_SHIFT) |
             (SPI1_CLK_RATE << SPI_CTRL_CLK_RATE_SHIFT);

  putreg32(ctrl_val, SPI_REG_CTRL(BK7258_SPI1_BASE));

  /* Step 5: Configure CFG: TX enable, RX disable */

  cfg_val = SPI_CFG_TX_EN_BIT;
  putreg32(cfg_val, SPI_REG_CFG(BK7258_SPI1_BASE));

  /* Step 6: Clear FIFOs */

  putreg32(SPI_INT_TX_FIFO_CLR | SPI_INT_RX_FIFO_CLR,
           SPI_REG_INT_STATUS(BK7258_SPI1_BASE));

  /* Verify CTRL was accepted */

  readback = getreg32(SPI_REG_CTRL(BK7258_SPI1_BASE));

  if (!(readback & SPI_CTRL_ENABLE_BIT))
    {
      syslog(LOG_ERR,
             "[lcd] SPI1 CTRL enable FAILED: wrote 0x%08lx, "
             "read 0x%08lx\n",
             (unsigned long)ctrl_val, (unsigned long)readback);
      g_hw_spi_capable = false;
      return -EIO;
    }

  g_hw_spi_capable = true;
  g_pins_in_spi_mode = false;

  syslog(LOG_INFO,
         "[lcd] SPI1 init OK: base=0x%08lX clk_rate=%d (~%d MHz)\n",
         (unsigned long)BK7258_SPI1_BASE, SPI1_CLK_RATE,
         26 / (SPI1_CLK_RATE + 1));

  return 0;
}

/****************************************************************************
 * Name: lcd_spi_deinit
 ****************************************************************************/

static void lcd_spi_deinit(void)
{
  if (!g_hw_spi_capable)
    {
      return;
    }

  putreg32(0, SPI_REG_CTRL(BK7258_SPI1_BASE));

  if (g_pins_in_spi_mode)
    {
      gpio_set_output_cached(g_lcd_left.sclk, &g_cache_sclk);
      gpio_set_output_cached(g_lcd_left.mosi, &g_cache_mosi);
      gpio_set_output_cached(g_lcd_left.cs,   &g_cache_cs);
      g_pins_in_spi_mode = false;
    }

  putreg32(g_saved_sys_clk_en, BK7258_SYS_CLK_ENABLE_REG);
  g_hw_spi_capable = false;
}

/****************************************************************************
 * Name: lcd_spi_pins_to_spi / lcd_spi_pins_to_gpio
 ****************************************************************************/

static void lcd_spi_pins_to_spi(void)
{
  if (g_pins_in_spi_mode)
    {
      return;
    }

  gpio_set_second_func(g_lcd_left.sclk, 0);
  gpio_set_second_func(g_lcd_left.cs,   0);
  gpio_set_second_func(g_lcd_left.mosi, 0);
  g_pins_in_spi_mode = true;
}

static void lcd_spi_pins_to_gpio(void)
{
  if (!g_pins_in_spi_mode)
    {
      return;
    }

  gpio_set_output_cached(g_lcd_left.sclk, &g_cache_sclk);
  gpio_set_output_cached(g_lcd_left.mosi, &g_cache_mosi);
  gpio_set_output_cached(g_lcd_left.cs,   &g_cache_cs);
  g_pins_in_spi_mode = false;
}

/****************************************************************************
 * Name: lcd_spi_write
 *
 * Description:
 *   Write data bytes via hardware SPI1 with timeout-protected polling.
 *   Returns 0 on success, -ETIMEDOUT if FIFO stalls.
 *
 ****************************************************************************/

static int lcd_spi_write(const uint8_t *data, size_t len)
{
  size_t remaining = len;
  const uint8_t *p = data;

  while (remaining > 0)
    {
      size_t chunk = remaining;
      uint32_t poll_cnt;

      if (chunk > SPI_CFG_TX_TRANS_LEN_MASK)
        {
          chunk = SPI_CFG_TX_TRANS_LEN_MASK;
        }

      /* Set TX transfer length */

      putreg32(SPI_CFG_TX_EN_BIT |
               (chunk << SPI_CFG_TX_TRANS_LEN_SHIFT),
               SPI_REG_CFG(BK7258_SPI1_BASE));

      /* Clear TX FIFO */

      putreg32(SPI_INT_TX_FIFO_CLR,
               SPI_REG_INT_STATUS(BK7258_SPI1_BASE));

      /* Feed FIFO with timeout-protected polling */

      size_t sent = 0;

      while (sent < chunk)
        {
          poll_cnt = SPI_POLL_TIMEOUT;

          while (!(getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE)) &
                   SPI_INT_TX_FIFO_WR_READY))
            {
              if (--poll_cnt == 0)
                {
                  uint32_t st =
                    getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE));

                  syslog(LOG_ERR,
                         "[lcd] SPI TX FIFO timeout, "
                         "INT_STATUS=0x%08lx sent=%lu/%lu\n",
                         (unsigned long)st,
                         (unsigned long)sent,
                         (unsigned long)chunk);
                  lcd_spi_pins_to_gpio();
                  return -ETIMEDOUT;
                }
            }

          /* Write up to SPI_FIFO_DEPTH bytes in this burst */

          size_t burst = chunk - sent;

          if (burst > SPI_FIFO_DEPTH)
            {
              burst = SPI_FIFO_DEPTH;
            }

          size_t i;

          for (i = 0; i < burst; i++)
            {
              putreg32(p[sent + i], SPI_REG_DATA(BK7258_SPI1_BASE));
            }

          sent += burst;
        }

      /* Wait for transfer to complete (tx_fifo_wr_ready = FIFO drained) */

      poll_cnt = SPI_POLL_TIMEOUT;

      while (!(getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE)) &
               SPI_INT_TX_FIFO_WR_READY))
        {
          if (--poll_cnt == 0)
            {
              uint32_t st =
                getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE));

              syslog(LOG_ERR,
                     "[lcd] SPI TX complete timeout, "
                     "INT_STATUS=0x%08lx\n",
                     (unsigned long)st);
              lcd_spi_pins_to_gpio();
              return -ETIMEDOUT;
            }
        }

      __asm__ volatile("nop; nop; nop; nop;");

      p += chunk;
      remaining -= chunk;
    }

  return 0;
}

