input.new_string:
static void lcd_fill_rect(uint16_t x0, uint16_t y0,
                          uint16_t x1, uint16_t y1,
                          uint16_t color)
{
  uint8_t ca[4];
  uint8_t ra[4];
  int npix = (int)(x1 - x0 + 1) * (int)(y1 - y0 + 1);

  /* CASET */

  ca[0] = (x0 >> 8) & 0xff;
  ca[1] = x0 & 0xff;
  ca[2] = (x1 >> 8) & 0xff;
  ca[3] = x1 & 0xff;
  lcd_send_cmd_data(0x2a, ca, 4);

  /* RASET */

  ra[0] = (y0 >> 8) & 0xff;
  ra[1] = y0 & 0xff;
  ra[2] = (y1 >> 8) & 0xff;
  ra[3] = y1 & 0xff;
  lcd_send_cmd_data(0x2b, ra, 4);

  /* RAMWR + pixel data — use HW SPI for bulk fill when available */

  lcd_send_cmd(0x2c);

#ifdef CONFIG_LCD_GC9D01_HW_SPI
  if (g_hw_spi_capable)
    {
      uint8_t tile[SPI_FIFO_DEPTH];
      uint8_t hi = (color >> 8) & 0xff;
      uint8_t lo = color & 0xff;
      int i;

      for (i = 0; i < (int)sizeof(tile); i += 2)
        {
          tile[i]     = hi;
          tile[i + 1] = lo;
        }

      gpio_write_fast(&g_cache_dc, 1);
      gpio_write_fast(&g_cache_cs, 0);
      lcd_spi_pins_to_spi();

      while (npix > 0)
        {
          int batch = npix;

          if (batch > (int)sizeof(tile) / 2)
            {
              batch = (int)sizeof(tile) / 2;
            }

          if (lcd_spi_write(tile, batch * 2) != 0)
            {
              goto fill_bb_fallback;
            }

          npix -= batch;
        }

      lcd_spi_pins_to_gpio();
      gpio_write_fast(&g_cache_cs, 1);
      return;
    }

fill_bb_fallback:
  /* Restore GPIO mode if HW SPI failed mid-transfer */

  if (g_pins_in_spi_mode)
    {
      lcd_spi_pins_to_gpio();
    }
#endif

  /* Bit-bang fallback */

  {
    uint8_t hi = (color >> 8) & 0xff;
    uint8_t lo = color & 0xff;
    int i;

    gpio_write_fast(&g_cache_dc, 1);
    gpio_write_fast(&g_cache_cs, 0);

    for (i = 0; i < npix; i++)
      {
        spi_write_byte(hi);
        spi_write_byte(lo);
      }

    gpio_write_fast(&g_cache_cs, 1);
  }
}

