static void lcd_spi_pins_to_spi(void)
{
  if (g_pins_in_spi_mode)
    {
      return;
    }

  gpio_set_second_func(g_lcd_left.sclk, 0);
  gpio_set_second_func(g_lcd_left.cs,   0);
  gpio_set_second_func(g_lcd_left.mosi, 0);
  g_pins_in_spi_mode = true;
}

static void lcd_spi_pins_to_gpio(void)
{
  if (!g_pins_in_spi_mode)
    {
      return;
    }

  gpio_set_output_cached(g_lcd_left.sclk, &g_cache_sclk);
  gpio_set_output_cached(g_lcd_left.mosi, &g_cache_mosi);
  gpio_set_output_cached(g_lcd_left.cs,   &g_cache_cs);
  g_pins_in_spi_mode = false;
}

