  g_saved_sys_clk_en = getreg32(BK7258_SYS_CLK_ENABLE_REG);
  putreg32(g_saved_sys_clk_en | SPI1_CLK_ENABLE_BIT,
           BK7258_SYS_CLK_ENABLE_REG);

  readback = getreg32(BK7258_SYS_CLK_ENABLE_REG);

  if (!(readback & SPI1_CLK_ENABLE_BIT))
    {
      syslog(LOG_ERR,
             "[lcd] SPI1 clock enable FAILED: wrote 0x%08lx, "
             "read 0x%08lx\n",
             (unsigned long)(g_saved_sys_clk_en | SPI1_CLK_ENABLE_BIT),
             (unsigned long)readback);
      g_hw_spi_capable = false;
      return -EIO;
    }

  /* Step 2: CLK_GATE_BYPASS first (ARMino: keep clock alive during reset) */

  putreg32(SPI_CLK_GATE_BYPASS, SPI_REG_GLOBAL_CTRL(BK7258_SPI1_BASE));

  /* Step 3: Soft-reset, then re-assert bypass */

  putreg32(SPI_SOFT_RESET, SPI_REG_GLOBAL_CTRL(BK7258_SPI1_BASE));
  putreg32(SPI_CLK_GATE_BYPASS, SPI_REG_GLOBAL_CTRL(BK7258_SPI1_BASE));

  /* Step 4: Configure CTRL
   *   master=1, enable=1, 8-bit, MSB first, CPOL=0, CPHA=0
   *   byte_interval=1 (required for BK7258 per spi_ll.h comment)
   *   clk_rate from Kconfig
   *
   *   CTRL bit summary (spi_struct.h REG_0x04):
   *     bit[23] enable     = 1
   *     bit[22] master     = 1
   *     bit[21] CPHA       = 0  (sample on leading edge)
   *     bit[20] CPOL       = 0  (idle low = SPI mode 0)
   *     bit[19] LSB first  = 0  (MSB first, cleared by default)
   *     bit[18] bit_width  = 0  (8-bit, cleared by default)
   *     bit[15:8] clk_rate = CONFIG_LCD_GC9D01_SPI_CLK_DIV
   *     bit[29:24] byte_interval = 1
   */

  ctrl_val = SPI_CTRL_MASTER_BIT |
             SPI_CTRL_ENABLE_BIT |
             (1u << SPI_CTRL_BYTE_INTERVAL_SHIFT) |
             ((uint32_t)SPI1_CLK_RATE << SPI_CTRL_CLK_RATE_SHIFT);

