44	static int binary_search(const uint32_t *array, uint32_t size, uint32_t target)
45	{
46		uint32_t left = 0;
47		uint32_t right = size - 1;
48		uint32_t mid = (left + right) / 2;
49	
50		while (left <= right && mid < size) {
51			mid = (left + right) / 2;
52			if (array[mid] == target) {
53				return mid;
54			}
55			if (target > array[mid]) {
56				right = mid - 1;
57			} else {
58				left = mid + 1;
59			}
60		}
61		return BK_FAIL;
62	}
63	#endif
