123	/* 1) src_clk=dco, div = ((dco_clk/2) / spi_clk) - 1
124	 * 2) src_clk=xtal_26M, div = xtal_26m / spi_clk - 1
125	 */
126	bk_err_t spi_hal_set_baud_rate(spi_hal_t *hal, uint32_t baud_rate)
127	{
128		uint32_t src_clk = 0;
129		uint32_t spi_clk = baud_rate;
130		uint32_t clk_div = 0;
131	
132		if (baud_rate > CONFIG_SPI_MAX_BAUD_RATE) {
133			HAL_LOGW("baud_rate(%d) not support, spi support max baud_rate:%d\r\n", baud_rate, CONFIG_SPI_MAX_BAUD_RATE);
134			spi_clk = CONFIG_SPI_MAX_BAUD_RATE;
135		}
136	
137	#if (CONFIG_SYSTEM_CTRL)
138		if (baud_rate <= CONFIG_XTAL_FREQ) {
139	#else
140		if (binary_search(s_spi_clk_list, ARRAY_SIZE(s_spi_clk_list), baud_rate) >= 0) {
141	#endif
142			HAL_LOGD("spi select src_clk xtal\r\n");
143			src_clk = CONFIG_XTAL_FREQ;
144	#if (CONFIG_SYSTEM_CTRL)
145			sys_hal_spi_select_clock(hal->id, SPI_CLK_XTAL);
146			clk_div = (src_clk / (2 * spi_clk)) & SPI_F_CLK_DIV_M;
147	#else
148			clk_set_spi_clk_26m(hal->id);
149			clk_div = (src_clk / spi_clk - 1) & SPI_F_CLK_DIV_M;
150	#endif
151		} else {
152	#if (CONFIG_SYSTEM_CTRL)
153			HAL_LOGD("spi select src_clk apll\r\n");
154	#if CONFIG_SOC_BK7256XX
155			//enable apll clock and set clock config
156			sys_hal_apll_en(true);
157			sys_hal_cb_manu_val_set(SPI_EN_APLL_MANU_VAL);
158			sys_hal_ana_reg11_vsel_set(SPI_EN_APLL_VSEL_VAL);
159			src_clk = SPI_APLL_98M;
160	#else
161			sys_hal_apll_en(1);
162			//set apll clock config
163			sys_hal_apll_cal_val_set(0x8973CA6F);
164			sys_hal_apll_config_set(0xC2A0AE86);
165			sys_hal_apll_spi_trigger_set(1);
166			delay(10);
167			sys_hal_apll_spi_trigger_set(0);
168			src_clk = SPI_APLL_98M;
169	#endif
170			sys_hal_spi_select_clock(hal->id, SPI_CLK_APLL);
171			clk_div = (src_clk / (2 * spi_clk)) & SPI_F_CLK_DIV_M;
172	#else
173			HAL_LOGD("spi select src_clk dco\r\n");
174			src_clk = CONFIG_DCO_FREQ >> 1; /* The spi clock is derived from the dco clock divided by 2 */
175			clk_set_spi_clk_dco(hal->id);
176			clk_div = (src_clk / spi_clk) & SPI_F_CLK_DIV_M;
177	#endif
178		}
179		HAL_LOGV("baud_rate = %d, src_clk = %d, clk_div = 0x%x.\r\n", baud_rate, src_clk, clk_div);
180		spi_ll_set_clk_div(hal->hw, clk_div);
181	
182		return BK_OK;
183	}
