381	/****************************************************************************
382	 * Name: lcd_spi_init
383	 *
384	 * Description:
385	 *   Initialize BK7258 SPI1 for left-screen LCD data transfers.
386	 *   Returns 0 on success, negative errno on failure.
387	 *   On failure, g_hw_spi_capable stays false — caller falls back to bit-bang.
388	 *
389	 *   Init sequence (matching ARMino spi_ll_init + spi_hal_configure):
390	 *     1. Enable SPI1 module clock, verify by read-back
391	 *     2. Set CLK_GATE_BYPASS (keep clock running during reset)
392	 *     3. Soft-reset
393	 *     4. Configure CTRL: master, mode 0, 8-bit, MSB first, byte_interval=1
394	 *     5. Configure CFG: TX enable
395	 *     6. Clear FIFOs
396	 *
397	 ****************************************************************************/

395	 *     6. Clear FIFOs
396	 *
397	 ****************************************************************************/
398	
399	static int lcd_spi_init(const lcd_pins_t *pins)
400	{
401	  uint32_t ctrl_val;
402	  uint32_t cfg_val;
403	  uint32_t readback;
404	  uint32_t cfg2;
405	  uint32_t cfg4;
406	  uint32_t func2;
407	  uint32_t func4;
408	  uintptr_t func_reg;
409	  uint32_t shift;
410	
411	  if (pins->sclk != 2 || pins->cs != 3 || pins->mosi != 4)
412	    {
413	      g_hw_spi_capable = false;
414	      return -EINVAL;
415	    }
416	
417	  /* Step 1: Enable SPI1 module clock, verify by read-back */
418	
419	  g_saved_sys_clk_en = getreg32(BK7258_SYS_CLK_ENABLE_REG);
420	  putreg32(g_saved_sys_clk_en | SPI1_CLK_ENABLE_BIT,
421	           BK7258_SYS_CLK_ENABLE_REG);
422	
423	  readback = getreg32(BK7258_SYS_CLK_ENABLE_REG);
424	
425	  if (!(readback & SPI1_CLK_ENABLE_BIT))
426	    {
427	      syslog(LOG_ERR,
428	             "[lcd] SPI1 clock enable FAILED: wrote 0x%08lx, "
429	             "read 0x%08lx\n",
430	             (unsigned long)(g_saved_sys_clk_en | SPI1_CLK_ENABLE_BIT),
431	             (unsigned long)readback);
432	      g_hw_spi_capable = false;
433	      return -EIO;
434	    }
435	
436	  /* Step 2: CLK_GATE_BYPASS first (ARMino: keep clock alive during reset) */
437	
438	  putreg32(SPI_CLK_GATE_BYPASS, SPI_REG_GLOBAL_CTRL(BK7258_SPI1_BASE));
439	
440	  /* Step 3: Soft-reset, then re-assert bypass */
441	
442	  putreg32(SPI_SOFT_RESET, SPI_REG_GLOBAL_CTRL(BK7258_SPI1_BASE));
443	  putreg32(SPI_CLK_GATE_BYPASS, SPI_REG_GLOBAL_CTRL(BK7258_SPI1_BASE));
444	
445	  /* Step 4: Configure CTRL
446	   *   master=1, enable=1, 8-bit, MSB first, CPOL=0, CPHA=0
447	   *   byte_interval=1 (required for BK7258 per spi_ll.h comment)
448	   *   clk_rate from Kconfig
449	   *
450	   *   CTRL bit summary (spi_struct.h REG_0x04):
451	   *     bit[23] enable     = 1
452	   *     bit[22] master     = 1
453	   *     bit[21] CPHA       = 0  (sample on leading edge)
454	   *     bit[20] CPOL       = 0  (idle low = SPI mode 0)
455	   *     bit[19] LSB first  = 0  (MSB first, cleared by default)
456	   *     bit[18] bit_width  = 0  (8-bit, cleared by default)
457	   *     bit[15:8] clk_rate = CONFIG_LCD_GC9D01_SPI_CLK_DIV
458	   *     bit[29:24] byte_interval = 1
459	   */
460	
461	  ctrl_val = SPI_CTRL_MASTER_BIT |
462	             SPI_CTRL_ENABLE_BIT |
463	             (1u << SPI_CTRL_BYTE_INTERVAL_SHIFT) |
464	             ((uint32_t)SPI1_CLK_RATE << SPI_CTRL_CLK_RATE_SHIFT);
465	
466	  putreg32(ctrl_val, SPI_REG_CTRL(BK7258_SPI1_BASE));
467	
468	  /* Step 5: Configure CFG: TX enable, RX disable */
469	
470	  cfg_val = SPI_CFG_TX_EN_BIT;
471	  putreg32(cfg_val, SPI_REG_CFG(BK7258_SPI1_BASE));
472	
473	  /* Step 6: Clear FIFOs */
474	
475	  putreg32(SPI_INT_TX_FIFO_CLR | SPI_INT_RX_FIFO_CLR,
476	           SPI_REG_INT_STATUS(BK7258_SPI1_BASE));
477	
478	  /* Verify CTRL was accepted + check SPI mode config */
479	
480	  readback = getreg32(SPI_REG_CTRL(BK7258_SPI1_BASE));
481	
482	  if (!(readback & SPI_CTRL_ENABLE_BIT))
483	    {
484	      syslog(LOG_ERR,
485	             "[lcd] SPI1 CTRL enable FAILED: wrote 0x%08lx, "
486	             "read 0x%08lx\n",
487	             (unsigned long)ctrl_val, (unsigned long)readback);
488	      g_hw_spi_capable = false;
489	      return -EIO;
490	    }
491	
492	  /* Verify SPI controller config matches GC9D01 requirements:
493	   *   mode 0 (CPOL=0, CPHA=0), MSB first, 8-bit, master
494	   */
495	
496	  if (readback & SPI_CTRL_CPHA_BIT)
497	    {
498	      syslog(LOG_WARNING,
499	             "[lcd] WARNING: CPHA=1 (expected 0 for mode 0)\n");
500	    }
501	
502	  if (readback & SPI_CTRL_CPOL_BIT)
503	    {
504	      syslog(LOG_WARNING,
505	             "[lcd] WARNING: CPOL=1 (expected 0 for mode 0)\n");
506	    }
507	
508	  if (readback & SPI_CTRL_LSB_FIRST_BIT)
509	    {
510	      syslog(LOG_WARNING,
511	             "[lcd] WARNING: LSB first (expected MSB first)\n");
512	    }
513	
