697	static int lcd_spi_write(const uint8_t *data, size_t len)
698	{
699	  size_t remaining = len;
700	  const uint8_t *p = data;
701	
702	  while (remaining > 0)
703	    {
704	      size_t chunk = remaining;
705	      uint32_t poll_cnt;
706	
