713	
714	      putreg32(SPI_CFG_TX_EN_BIT |
715	               (chunk << SPI_CFG_TX_TRANS_LEN_SHIFT),
716	               SPI_REG_CFG(BK7258_SPI1_BASE));
717	
718	      /* Clear TX FIFO */
719	
720	      putreg32(SPI_INT_TX_FIFO_CLR,
721	               SPI_REG_INT_STATUS(BK7258_SPI1_BASE));
722	
723	      /* Feed FIFO with timeout-protected polling */
724	
725	      size_t sent = 0;
726	
727	      while (sent < chunk)
728	        {
729	          poll_cnt = SPI_POLL_TIMEOUT;
730	
731	          while (!(getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE)) &
732	                   SPI_INT_TX_FIFO_WR_READY))
733	            {
734	              if (--poll_cnt == 0)
735	                {
736	                  uint32_t st =
737	                    getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE));
738	
739	                  syslog(LOG_ERR,
740	                         "[lcd] SPI TX FIFO timeout, "
741	                         "INT_STATUS=0x%08lx sent=%lu/%lu\n",
742	                         (unsigned long)st,
743	                         (unsigned long)sent,
744	                         (unsigned long)chunk);
745	                  lcd_spi_pins_to_gpio();
746	                  return -ETIMEDOUT;
747	                }
748	            }
749	
750	          /* Write up to SPI_FIFO_DEPTH bytes in this burst */
751	
752	          size_t burst = chunk - sent;
753	
754	          if (burst > SPI_FIFO_DEPTH)
755	            {
756	              burst = SPI_FIFO_DEPTH;
757	            }
758	
759	          size_t i;
760	
761	          for (i = 0; i < burst; i++)
