699	static int lcd_spi_write(const uint8_t *data, size_t len)
700	{
701	  size_t remaining = len;
702	  const uint8_t *p = data;
703	
704	  while (remaining > 0)
705	    {
706	      size_t chunk = remaining;
707	      uint32_t poll_cnt;
708	
709	      if (chunk > SPI_CFG_TX_TRANS_LEN_MASK)
710	        {
711	          chunk = SPI_CFG_TX_TRANS_LEN_MASK;
712	        }
713	
714	      /* Set TX transfer length */
715	
716	      putreg32(SPI_CFG_TX_EN_BIT |
717	               (chunk << SPI_CFG_TX_TRANS_LEN_SHIFT),
718	               SPI_REG_CFG(BK7258_SPI1_BASE));
719	
720	      /* Clear TX FIFO */
721	
722	      putreg32(SPI_INT_TX_FIFO_CLR,
723	               SPI_REG_INT_STATUS(BK7258_SPI1_BASE));
724	
725	      /* Feed FIFO with timeout-protected polling */
726	
727	      size_t sent = 0;
728	
729	      while (sent < chunk)
730	        {
731	          poll_cnt = SPI_POLL_TIMEOUT;
732	
733	          while (!(getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE)) &
734	                   SPI_INT_TX_FIFO_WR_READY))
735	            {
736	              if (--poll_cnt == 0)
737	                {
738	                  uint32_t st =
739	                    getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE));
740	
741	                  syslog(LOG_ERR,
742	                         "[lcd] SPI TX FIFO timeout, "
743	                         "INT_STATUS=0x%08lx sent=%lu/%lu\n",
744	                         (unsigned long)st,
745	                         (unsigned long)sent,
746	                         (unsigned long)chunk);
747	                  lcd_spi_pins_to_gpio();
748	                  return -ETIMEDOUT;
749	                }
750	            }
751	
752	          /* Write up to SPI_FIFO_DEPTH bytes in this burst */
753	
754	          size_t burst = chunk - sent;
755	
756	          if (burst > SPI_FIFO_DEPTH)
757	            {
758	              burst = SPI_FIFO_DEPTH;
759	            }
760	
761	          size_t i;
762	
763	          for (i = 0; i < burst; i++)
764	            {
765	              putreg32(p[sent + i], SPI_REG_DATA(BK7258_SPI1_BASE));
766	            }
767	
768	          sent += burst;
769	        }
770	
771	      /* Wait for transfer to complete (tx_fifo_wr_ready = FIFO drained) */
772	
773	      poll_cnt = SPI_POLL_TIMEOUT;
774	
775	      while (!(getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE)) &
776	               SPI_INT_TX_FIFO_WR_READY))
777	        {
778	          if (--poll_cnt == 0)
779	            {
780	              uint32_t st =
781	                getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE));
782	
783	              syslog(LOG_ERR,
784	                     "[lcd] SPI TX complete timeout, "
785	                     "INT_STATUS=0x%08lx\n",
786	                     (unsigned long)st);
787	              lcd_spi_pins_to_gpio();
788	              return -ETIMEDOUT;
789	            }
790	        }
791	
792	      /* Extra NOPs to ensure last byte is fully clocked out on wire */
793	
794	      __asm__ volatile("nop; nop; nop; nop;");
795	      __asm__ volatile("nop; nop; nop; nop;");
796	
797	      p += chunk;
798	      remaining -= chunk;
799	    }
800	
801	  /* Final drain: wait until FIFO is completely empty and last byte
802	   * has been clocked out.  tx_fifo_wr_ready = FIFO has space,
803	   * which is true when empty.  Extra NOPs for last-bit timing.
804	   */
805	
806	  {
807	    uint32_t poll_cnt = SPI_POLL_TIMEOUT;
808	
809	    while (!(getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE)) &
810	             SPI_INT_TX_FIFO_WR_READY))
