812	        if (--poll_cnt == 0)
813	          {
814	            syslog(LOG_ERR,
815	                   "[lcd] SPI final drain timeout\n");
816	            lcd_spi_pins_to_gpio();
817	            return -ETIMEDOUT;
818	          }
819	      }
820	  }
