      poll_cnt = SPI_POLL_TIMEOUT;

      while (!(getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE)) &
               SPI_INT_TX_FIFO_WR_READY))
        {
          if (--poll_cnt == 0)
            {
              uint32_t st =
                getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE));

              syslog(LOG_ERR,
                     "[lcd] SPI TX complete timeout, "
                     "INT_STATUS=0x%08lx\n",
                     (unsigned long)st);
              lcd_spi_pins_to_gpio();
              return -ETIMEDOUT;
            }
        }

      /* Extra NOPs to ensure last byte is fully clocked out on wire */

      __asm__ volatile("nop; nop; nop; nop;");
      __asm__ volatile("nop; nop; nop; nop;");

      p += chunk;
      remaining -= chunk;
