699	static int lcd_spi_write(const uint8_t *data, size_t len)
700	{
701	  size_t remaining = len;
702	  const uint8_t *p = data;
703	
704	  while (remaining > 0)
705	    {
706	      size_t chunk = remaining;
707	      uint32_t poll_cnt;
708	      uint32_t st;
709	
710	      if (chunk > SPI_CFG_TX_TRANS_LEN_MASK)
711	        {
712	          chunk = SPI_CFG_TX_TRANS_LEN_MASK;
713	        }
714	
715	      /* Clear all pending interrupts + TX FIFO before starting chunk.
716	       * This clears stale tx_underflow_int from previous transfer.
717	       * ARMino: spi_hal_clear_tx_fifo + spi_hal_configure clear step.
718	       */
719	
720	      putreg32(SPI_INT_TX_FIFO_CLR | SPI_INT_RX_FIFO_CLR,
721	               SPI_REG_INT_STATUS(BK7258_SPI1_BASE));
722	      putreg32(0xFFFFFFFF, SPI_REG_INT_STATUS(BK7258_SPI1_BASE));
723	
724	      /* Set TX transfer length + enable TX */
725	
726	      putreg32(SPI_CFG_TX_EN_BIT |
727	               (chunk << SPI_CFG_TX_TRANS_LEN_SHIFT),
728	               SPI_REG_CFG(BK7258_SPI1_BASE));
729	
730	      /* Feed FIFO with timeout-protected polling.
731	       * ARMino: spi_id_write_bytes_common — poll tx_fifo_wr_ready,
732	       * write one byte at a time.
733	       */
734	
735	      size_t sent = 0;
736	
737	      while (sent < chunk)
738	        {
739	          poll_cnt = SPI_POLL_TIMEOUT;
740	
741	          while (!(getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE)) &
742	                   SPI_INT_TX_FIFO_WR_READY))
743	            {
744	              if (--poll_cnt == 0)
745	                {
746	                  st = getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE));
747	
748	                  syslog(LOG_ERR,
749	                         "[lcd] SPI TX FIFO timeout, "
750	                         "INT_STATUS=0x%08lx sent=%lu/%lu\n",
751	                         (unsigned long)st,
752	                         (unsigned long)sent,
753	                         (unsigned long)chunk);
754	                  lcd_spi_pins_to_gpio();
755	                  return -ETIMEDOUT;
756	                }
757	            }
758	
759	          /* Write up to SPI_FIFO_DEPTH bytes in this burst */
760	
761	          size_t burst = chunk - sent;
762	
763	          if (burst > SPI_FIFO_DEPTH)
764	            {
765	              burst = SPI_FIFO_DEPTH;
766	            }
767	
768	          size_t i;
769	
770	          for (i = 0; i < burst; i++)
771	            {
772	              putreg32(p[sent + i], SPI_REG_DATA(BK7258_SPI1_BASE));
773	            }
774	
775	          sent += burst;
776	        }
777	
778	      /* All bytes are now in the FIFO.  Clear any stale tx_finish /
779	       * tx_underflow status accumulated while feeding, then wait for the
780	       * FIFO to drain.
781	       *
782	       * NOTE: tx_finish_int (bit13) does NOT assert in this streaming mode
783	       * (no ISR / trans-len completion path is taken), but the controller
784	       * reliably raises tx_underflow_int (bit11) once the shifter empties
785	       * the FIFO.  We therefore accept EITHER bit as "all bytes clocked
786	       * out".  Clear first and wait for a FRESH assertion, otherwise a
787	       * stale underflow from a mid-feed gap would end the wait early.
788	       */
789	
790	      putreg32(SPI_INT_TX_FINISH | SPI_INT_TX_UNDERFLOW,
791	               SPI_REG_INT_STATUS(BK7258_SPI1_BASE));
792	
793	      poll_cnt = SPI_POLL_TIMEOUT;
794	
795	      for (;;)
796	        {
797	          st = getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE));
798	
799	          if (st & (SPI_INT_TX_FINISH | SPI_INT_TX_UNDERFLOW))
800	            {
801	              break;  /* FIFO drained -> all bytes clocked out */
802	            }
803	
804	          if (--poll_cnt == 0)
805	            {
806	              syslog(LOG_ERR,
807	                     "[lcd] SPI TX finish timeout, "
808	                     "INT_STATUS=0x%08lx sent=%lu/%lu\n",
809	                     (unsigned long)st,
810	                     (unsigned long)sent,
811	                     (unsigned long)chunk);
812	              lcd_spi_pins_to_gpio();
813	              return -ETIMEDOUT;
814	            }
815	        }
816	
817	      /* Let the final byte finish clocking out of the shift register
818	       * (underflow asserts when the FIFO empties, but the last byte may
819	       * still be shifting: 8 bits @ ~2 MHz is about 4 us).
820	       */
821	
822	      up_udelay(10);
823	
824	      /* Clear the completion bits (write-1-to-clear). */
825	
826	      putreg32(st & (SPI_INT_TX_FINISH | SPI_INT_TX_UNDERFLOW),
827	               SPI_REG_INT_STATUS(BK7258_SPI1_BASE));
828	
829	      p += chunk;
830	      remaining -= chunk;
831	    }
832	
833	  /* Safety margin: ensure last clock edge has propagated */
834	
835	  __asm__ volatile("nop; nop; nop; nop;");
836	  __asm__ volatile("nop; nop; nop; nop;");
837	
838	  return 0;
839	}
