static int lcd_spi_write(const uint8_t *data, size_t len)
{
  size_t remaining = len;
  const uint8_t *p = data;

  while (remaining > 0)
    {
      size_t chunk = remaining;
      uint32_t poll_cnt;
      uint32_t st;

      if (chunk > SPI_CFG_TX_TRANS_LEN_MASK)
        {
          chunk = SPI_CFG_TX_TRANS_LEN_MASK;
        }

      /* Clear all pending interrupts + TX FIFO before starting chunk.
       * This clears stale tx_underflow_int from previous transfer.
       * ARMino: spi_hal_clear_tx_fifo + spi_hal_configure clear step.
       */

      putreg32(SPI_INT_TX_FIFO_CLR | SPI_INT_RX_FIFO_CLR,
               SPI_REG_INT_STATUS(BK7258_SPI1_BASE));
      putreg32(0xFFFFFFFF, SPI_REG_INT_STATUS(BK7258_SPI1_BASE));

      /* Set TX transfer length + enable TX */

      putreg32(SPI_CFG_TX_EN_BIT |
               (chunk << SPI_CFG_TX_TRANS_LEN_SHIFT),
               SPI_REG_CFG(BK7258_SPI1_BASE));

      /* Feed FIFO with timeout-protected polling.
       * ARMino: spi_id_write_bytes_common — poll tx_fifo_wr_ready,
       * write one byte at a time.
       */

      size_t sent = 0;

      while (sent < chunk)
        {
          poll_cnt = SPI_POLL_TIMEOUT;

          while (!(getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE)) &
                   SPI_INT_TX_FIFO_WR_READY))
            {
              if (--poll_cnt == 0)
                {
                  st = getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE));

                  syslog(LOG_ERR,
                         "[lcd] SPI TX FIFO timeout, "
                         "INT_STATUS=0x%08lx sent=%lu/%lu\n",
                         (unsigned long)st,
                         (unsigned long)sent,
                         (unsigned long)chunk);
                  lcd_spi_pins_to_gpio();
                  return -ETIMEDOUT;
                }
            }

          /* Write up to SPI_FIFO_DEPTH bytes in this burst */

          size_t burst = chunk - sent;

          if (burst > SPI_FIFO_DEPTH)
            {
              burst = SPI_FIFO_DEPTH;
            }

          size_t i;

          for (i = 0; i < burst; i++)
            {
              putreg32(p[sent + i], SPI_REG_DATA(BK7258_SPI1_BASE));
            }

          sent += burst;
        }

      /* All bytes are now in the FIFO.  Clear any stale tx_finish /
       * tx_underflow status accumulated while feeding, then wait for the
       * FIFO to drain.
       *
       * NOTE: tx_finish_int (bit13) does NOT assert in this streaming mode
       * (no ISR / trans-len completion path is taken), but the controller
       * reliably raises tx_underflow_int (bit11) once the shifter empties
       * the FIFO.  We therefore accept EITHER bit as "all bytes clocked
       * out".  Clear first and wait for a FRESH assertion, otherwise a
       * stale underflow from a mid-feed gap would end the wait early.
       */

      putreg32(SPI_INT_TX_FINISH | SPI_INT_TX_UNDERFLOW,
               SPI_REG_INT_STATUS(BK7258_SPI1_BASE));

      poll_cnt = SPI_POLL_TIMEOUT;

      for (;;)
        {
          st = getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE));

          if (st & (SPI_INT_TX_FINISH | SPI_INT_TX_UNDERFLOW))
            {
              break;  /* FIFO drained -> all bytes clocked out */
            }

          if (--poll_cnt == 0)
            {
              syslog(LOG_ERR,
                     "[lcd] SPI TX finish timeout, "
                     "INT_STATUS=0x%08lx sent=%lu/%lu\n",
                     (unsigned long)st,
                     (unsigned long)sent,
                     (unsigned long)chunk);
              lcd_spi_pins_to_gpio();
              return -ETIMEDOUT;
            }
        }

      /* Let the final byte finish clocking out of the shift register
       * (underflow asserts when the FIFO empties, but the last byte may
       * still be shifting: 8 bits @ ~2 MHz is about 4 us).
       */

      up_udelay(10);

      /* Clear the completion bits (write-1-to-clear). */

      putreg32(st & (SPI_INT_TX_FINISH | SPI_INT_TX_UNDERFLOW),
               SPI_REG_INT_STATUS(BK7258_SPI1_BASE));

      p += chunk;
      remaining -= chunk;
    }

  /* Safety margin: ensure last clock edge has propagated */

  __asm__ volatile("nop; nop; nop; nop;");
  __asm__ volatile("nop; nop; nop; nop;");

  return 0;
}

