static int lcd_spi_write(const uint8_t *data, size_t len)
{
  size_t remaining = len;
  const uint8_t *p = data;

  while (remaining > 0)
    {
      size_t chunk = remaining;
      uint32_t poll_cnt;
      uint32_t st;
      uint32_t cfg;

      if (chunk > SPI_CFG_TX_TRANS_LEN_MASK)
        {
          chunk = SPI_CFG_TX_TRANS_LEN_MASK;
        }

      /* [A] Clear FIFO + all pending interrupts BEFORE starting chunk.
       * ARMino: spi_hal_clear_tx_fifo → spi_ll_clear_tx_fifo (bit16=1)
       *         spi_hal_configure last step → spi_ll_clear_int_status
       *           (writes 1 to bits 8,9,10,11,12 individually)
       * We do the same: clear FIFO first, then clear all status bits.
       * After this point we do NOT touch INT_STATUS until tx_finish fires.
       */

      putreg32(SPI_INT_TX_FIFO_CLR | SPI_INT_RX_FIFO_CLR,
               SPI_REG_INT_STATUS(BK7258_SPI1_BASE));
      putreg32(0xFFFFFFFF, SPI_REG_INT_STATUS(BK7258_SPI1_BASE));

      /* [B] Set TX transfer length — READ-MODIFY-WRITE on CFG.
       * ARMino: spi_ll_set_tx_trans_len → hw->cfg.tx_trans_len = len
       *         (bit-field read-modify-write, preserves tx_finish_int_en bit2)
       * Previous code did a full word putreg32 that wiped bit2 (tx_finish_int_en),
       * which is why bit13 (tx_finish_int) never asserted.
       */

      cfg = getreg32(SPI_REG_CFG(BK7258_SPI1_BASE));
      cfg &= ~(SPI_CFG_TX_TRANS_LEN_MASK << SPI_CFG_TX_TRANS_LEN_SHIFT);
      cfg |= (chunk << SPI_CFG_TX_TRANS_LEN_SHIFT);
      cfg |= SPI_CFG_TX_EN_BIT;     /* tx_en = 1 */
      cfg |= (1u << 2);             /* tx_finish_int_en = 1 (bit2) */
      putreg32(cfg, SPI_REG_CFG(BK7258_SPI1_BASE));

      /* [C] Feed FIFO byte-by-byte with per-byte ready polling.
       * ARMino: spi_id_write_bytes_common —
       *   for (i = 0; i < size; i++) {
       *     BK_WHILE (!spi_hal_is_tx_fifo_wr_ready(hal));
       *     spi_hal_write_byte(hal, buf[i]);
       *   }
       * We match this exactly: one byte per ready check.
       */

      size_t i;

      for (i = 0; i < chunk; i++)
        {
          poll_cnt = SPI_POLL_TIMEOUT;

          while (!(getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE)) &
                   SPI_INT_TX_FIFO_WR_READY))
            {
              if (--poll_cnt == 0)
                {
                  st = getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE));

                  syslog(LOG_ERR,
                         "[lcd] SPI TX FIFO timeout, "
                         "INT_STATUS=0x%08lx sent=%lu/%lu\n",
                         (unsigned long)st,
                         (unsigned long)i,
                         (unsigned long)chunk);
                  lcd_spi_pins_to_gpio();
                  return -ETIMEDOUT;
                }
            }

          putreg32(p[i], SPI_REG_DATA(BK7258_SPI1_BASE));
        }

      /* [D] Wait for TX finish (bit13) — the controller has clocked out
       * all tx_trans_len bytes.
       * ARMino: ISR checks spi_ll_is_tx_finish_int_triggered(status, BIT(13)),
       *         then calls bk_spi_clr_tx → disable_tx.
       * We poll bit13 directly.  Also accept bit11 (tx_underflow) as a
       * secondary indicator — it fires when the FIFO drains faster than
       * expected, which is benign and means data was sent.
       *
       * CRITICAL: do NOT clear INT_STATUS between feeding and waiting.
       * The previous code cleared tx_finish/tx_underflow after feeding,
       * then waited for them to re-assert — but with trans_len set the
       * controller stops after chunk bytes, so no new underflow fires.
       */

      poll_cnt = SPI_POLL_TIMEOUT;

      for (;;)
        {
          st = getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE));

          if (st & (SPI_INT_TX_FINISH | SPI_INT_TX_UNDERFLOW))
            {
              break;
            }

          if (--poll_cnt == 0)
            {
              syslog(LOG_ERR,
                     "[lcd] SPI TX finish timeout, "
                     "INT_STATUS=0x%08lx sent=%lu/%lu\n",
                     (unsigned long)st,
                     (unsigned long)chunk,
                     (unsigned long)chunk);
              lcd_spi_pins_to_gpio();
              return -ETIMEDOUT;
            }
        }

      /* Let the last byte fully shift out (8 bits @ ~2 MHz ≈ 4 μs) */

      up_udelay(10);

      /* [E] Clear completion bits (write-1-to-clear), then disable TX.
       * ARMino: bk_spi_clr_tx → disable_tx_fifo_int + disable_tx
       */

      putreg32(st & (SPI_INT_TX_FINISH | SPI_INT_TX_UNDERFLOW),
               SPI_REG_INT_STATUS(BK7258_SPI1_BASE));

      cfg = getreg32(SPI_REG_CFG(BK7258_SPI1_BASE));
      cfg &= ~SPI_CFG_TX_EN_BIT;    /* tx_en = 0 */
      putreg32(cfg, SPI_REG_CFG(BK7258_SPI1_BASE));

      p += chunk;
      remaining -= chunk;
    }

  return 0;
}

