1550	/****************************************************************************
1551	 * Name: bk7258_lcd_blit_rgb565
1552	 *
1553	 * Description:
1554	 *   Blit a full RGB565 framebuffer to the LCD.
1555	 *   Sends CASET/RASET/RAMWR then streams pixel data in rows.
1556	 *
1557	 *   panel: 0=left (SPI1 HW), 1=right (bit-bang), other=left
1558	 *
1559	 ****************************************************************************/
1560	
1561	void bk7258_lcd_blit_rgb565(int panel,
1562	                             uint16_t x0, uint16_t y0,
1563	                             uint16_t w, uint16_t h,
1564	                             const uint8_t *rgb565)
1565	{
1566	  uint8_t ca[4];
1567	  uint8_t ra[4];
1568	  uint16_t x1 = x0 + w - 1;
1569	  uint16_t y1 = y0 + h - 1;
1570	  int row;
1571	  int row_bytes = (int)w * 2;
1572	
1573	  /* Auto-switch panel if different from current */
1574	
1575	  if (panel == 1 && g_active_pins != &g_lcd_right)
1576	    {
1577	      lcd_set_pins(&g_lcd_right);
1578	      lcd_setup_pins(&g_lcd_right);
1579	    }
1580	  else if (panel != 1 && g_active_pins != &g_lcd_left)
1581	    {
1582	      lcd_set_pins(&g_lcd_left);
1583	      lcd_setup_pins(&g_lcd_left);
1584	    }
1585	
1586	  /* CASET */
1587	
1588	  ca[0] = (x0 >> 8) & 0xff;
1589	  ca[1] = x0 & 0xff;
1590	  ca[2] = (x1 >> 8) & 0xff;
1591	  ca[3] = x1 & 0xff;
1592	  lcd_send_cmd_data(0x2a, ca, 4);
1593	
1594	  /* RASET */
1595	
1596	  ra[0] = (y0 >> 8) & 0xff;
1597	  ra[1] = y0 & 0xff;
1598	  ra[2] = (y1 >> 8) & 0xff;
1599	  ra[3] = y1 & 0xff;
1600	  lcd_send_cmd_data(0x2b, ra, 4);
1601	
1602	  /* RAMWR */
1603	
1604	  lcd_send_cmd(0x2c);
1605	
1606	#ifdef CONFIG_LCD_GC9D01_HW_SPI
1607	  /* Use HW SPI for pixel data when available (left screen only) */
1608	
1609	  if (lcd_hw_spi_usable())
1610	    {
1611	      for (row = 0; row < (int)h; row++)
1612	        {
1613	          const uint8_t *rowp = rgb565 + row * row_bytes;
1614	
1615	          gpio_write_fast(&g_cache_dc, 1);
1616	          gpio_write_fast(&g_cache_cs, 0);
1617	          lcd_spi_pins_to_spi();
1618	
1619	          if (lcd_spi_write(rowp, row_bytes) != 0)
1620	            {
1621	              /* Timeout — switch to bit-bang for remaining rows */
1622	
1623	              lcd_spi_pins_to_gpio();
1624	              goto blit_bb_rows;
1625	            }
1626	
1627	          lcd_spi_pins_to_gpio();
1628	          gpio_write_fast(&g_cache_cs, 1);
1629	        }
1630	
1631	      return;
1632	    }
1633	
1634	blit_bb_rows:
1635	  /* If HW SPI failed mid-frame, continue with bit-bang from current row */
1636	
1637	  if (g_pins_in_spi_mode)
1638	    {
1639	      lcd_spi_pins_to_gpio();
1640	    }
1641	#endif
1642	
1643	  /* Bit-bang fallback (or remaining rows after HW SPI timeout) */
1644	
1645	  for (; row < (int)h; row++)
1646	    {
1647	      const uint8_t *rowp = rgb565 + row * row_bytes;
1648	      int i;
1649	
1650	      gpio_write_fast(&g_cache_dc, 1);
1651	      gpio_write_fast(&g_cache_cs, 0);
1652	
1653	      for (i = 0; i < row_bytes; i++)
1654	        {
1655	          spi_write_byte(rowp[i]);
1656	        }
1657	
1658	      gpio_write_fast(&g_cache_cs, 1);
