/****************************************************************************
 * Name: lcdtest_chunk
 *
 * Description:
 *   Probe SPI chunk sizes: fill the left screen with a solid color using
 *   a single lcd_spi_write() call of the specified byte count.
 *   Reports whether the transfer timed out, and at what byte offset.
 *   Usage: lcdtest chunk <bytes>   (default 1024, max 51200)
 *
 ****************************************************************************/

static int lcdtest_chunk(int argc, char *argv[])
{
  int chunk_bytes = SPI_MAX_CHUNK_BYTES;
  int total = 160 * 160 * 2;  /* full screen RGB565 */
  size_t sent = 0;
  int ret;

  if (argc > 2)
    {
      chunk_bytes = atoi(argv[2]);
    }

  if (chunk_bytes < 2)
    {
      chunk_bytes = 2;
    }

  if (chunk_bytes > total)
    {
      chunk_bytes = total;
    }

  /* Ensure left screen is set up */

  if (g_active_pins != &g_lcd_left)
    {
      lcd_set_pins(&g_lcd_left);
      lcd_setup_pins(&g_lcd_left);
    }

  /* CASET + RASET for full screen */

  {
    uint8_t ca[4] = {0, 0, 0, 159};
    uint8_t ra[4] = {0, 0, 0, 159};

    lcd_send_cmd_data(0x2a, ca, 4);
    lcd_send_cmd_data(0x2b, ra, 4);
  }

  /* Build a static tile buffer filled with blue (0x001F) */

  static uint8_t tile[51200];
  int fill = chunk_bytes;

  if (fill > (int)sizeof(tile))
    {
      fill = (int)sizeof(tile);
    }

  {
    int i;

    for (i = 0; i < fill; i += 2)
      {
        tile[i]     = 0x00;  /* R5G3 high byte */
        tile[i + 1] = 0x1f;  /* G3B5 low byte — blue */
      }
  }

  syslog(LOG_INFO,
         "[chunk] test: chunk_bytes=%d total=%d\n",
         chunk_bytes, total);

  /* RAMWR — single CS-low session */

  lcd_send_cmd(0x2c);
  gpio_write_fast(&g_cache_dc, 1);
  gpio_write_fast(&g_cache_cs, 0);
  lcd_spi_pins_to_spi();

  /* Override the static chunk limit for this test */

  {
    /* Feed the full screen using the requested chunk size.
     * We temporarily write SPI_MAX_CHUNK_BYTES and restore after.
     * Instead, we just loop lcd_spi_write with chunk_bytes-sized buffers.
     */

    const uint8_t *p = tile;
    int remaining = total;

    while (remaining > 0)
      {
        int batch = remaining;

        if (batch > chunk_bytes)
          {
            batch = chunk_bytes;
          }

        sent = 0;
        ret = lcd_spi_write(p, (size_t)batch, &sent);

        if (ret != 0)
          {
            syslog(LOG_ERR,
                   "[chunk] TIMEOUT at batch: sent=%lu/%d "
                   "total_done=%lu/%d\n",
                   (unsigned long)sent, batch,
                   (unsigned long)(total - remaining + sent), total);
            gpio_write_fast(&g_cache_cs, 1);
            return ret;
          }

        p += batch;
        remaining -= batch;
      }
  }

  lcd_spi_pins_to_gpio();
  gpio_write_fast(&g_cache_cs, 1);

  syslog(LOG_INFO,
         "[chunk] PASS: chunk_bytes=%d filled %d bytes OK\n",
         chunk_bytes, total);
  return 0;
}

