/****************************************************************************
 * Name: lcdtest_chunk
 *
 * Description:
 *   Probe SPI chunk sizes: fill the left screen with a solid color using
 *   lcd_spi_write() at the specified chunk size.
 *   Reports whether the transfer timed out, and at what byte offset.
 *   Usage: lcdtest chunk <bytes>   (default 1024, range 2..4095, even only)
 *
 ****************************************************************************/

static int lcdtest_chunk(int argc, char *argv[])
{
  static uint8_t tile[4096];  /* one chunk, filled blue */
  int chunk_bytes = SPI_MAX_CHUNK_BYTES;
  int total = 160 * 160 * 2;  /* full screen RGB565 */
  uint32_t saved_max = g_spi_max_chunk;
  size_t sent = 0;
  int ret;
  int i;
  clock_t t0;
  uint32_t elapsed_ms;
  uint32_t throughput_kbps;

  if (argc > 2)
    {
      chunk_bytes = atoi(argv[2]);
    }

  /* Validate: 2..4095, must be even (RGB565 = 2 bytes/pixel) */

  if (chunk_bytes < 2 || chunk_bytes > 4095)
    {
      syslog(LOG_ERR,
             "[chunk] error: chunk_bytes=%d out of range (2..4095)\n",
             chunk_bytes);
      return -EINVAL;
    }

  if (chunk_bytes & 1)
    {
      syslog(LOG_ERR,
             "[chunk] error: chunk_bytes=%d must be even "
             "(RGB565 = 2 bytes/pixel)\n",
             chunk_bytes);
      return -EINVAL;
    }

  /* Ensure left screen is set up */

  if (g_active_pins != &g_lcd_left)
    {
      lcd_set_pins(&g_lcd_left);
      lcd_setup_pins(&g_lcd_left);
    }

  /* CASET + RASET for full screen */

  {
    uint8_t ca[4] = {0, 0, 0, 159};
    uint8_t ra[4] = {0, 0, 0, 159};

    lcd_send_cmd_data(0x2a, ca, 4);
    lcd_send_cmd_data(0x2b, ra, 4);
  }

  /* Fill tile buffer entirely with blue (0x001F).
   * Reused for every batch; only needs to be one chunk wide.
   */

  {
    int fill = chunk_bytes;

    if (fill > (int)sizeof(tile))
      {
        fill = (int)sizeof(tile);
      }

    for (i = 0; i < fill; i += 2)
      {
        tile[i]     = 0x00;  /* R5G3 high byte */
        tile[i + 1] = 0x1f;  /* G3B5 low byte — blue */
      }
  }

  /* Override runtime chunk limit for this test */

  g_spi_max_chunk = (uint32_t)chunk_bytes;

  syslog(LOG_INFO,
         "[chunk] test: chunk_bytes=%d total=%d\n",
         chunk_bytes, total);

  /* RAMWR — single CS-low session */

  lcd_send_cmd(0x2c);
  gpio_write_fast(&g_cache_dc, 1);
  gpio_write_fast(&g_cache_cs, 0);
  lcd_spi_pins_to_spi();

  t0 = clock_systime_ticks();

  /* Feed the full screen in chunk_bytes-sized batches */

  {
    int remaining = total;

    while (remaining > 0)
      {
        int batch = remaining;

        if (batch > chunk_bytes)
          {
            batch = chunk_bytes;
          }

        sent = 0;
        ret = lcd_spi_write(tile, (size_t)batch, &sent);

        if (ret != 0)
          {
            elapsed_ms = (uint32_t)TICK2MSEC(clock_systime_ticks() - t0);
            syslog(LOG_ERR,
                   "[chunk] TIMEOUT: chunk_bytes=%d "
                   "sent=%lu/%d total_done=%lu/%d elapsed=%lums\n",
                   chunk_bytes,
                   (unsigned long)sent, batch,
                   (unsigned long)(total - remaining + sent), total,
                   (unsigned long)elapsed_ms);
            lcd_spi_pins_to_gpio();
            gpio_write_fast(&g_cache_cs, 1);
            g_spi_max_chunk = saved_max;
            return ret;
          }

        remaining -= batch;
      }
  }

  elapsed_ms = (uint32_t)TICK2MSEC(clock_systime_ticks() - t0);
  lcd_spi_pins_to_gpio();
  gpio_write_fast(&g_cache_cs, 1);
  g_spi_max_chunk = saved_max;

  /* Avoid division by zero */

  if (elapsed_ms == 0)
    {
      elapsed_ms = 1;
    }

  throughput_kbps = (uint32_t)total * 1000u / elapsed_ms / 1024u;

  syslog(LOG_INFO,
         "[chunk] PASS: chunk_bytes=%d filled %d bytes OK "
         "elapsed=%lums throughput=%lu KB/s\n",
         chunk_bytes, total,
         (unsigned long)elapsed_ms,
         (unsigned long)throughput_kbps);
  return 0;
}

